INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-clarify-01', 'lesson-pedagogy-a1-clarify', 1, 'sentence', 'Please repeat that.', 'Por favor, repita isso.', '/pliːz rɪˈpiːt ðæt/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"repeat","pos":"verb","ipa":"/rɪˈpiːt/","gloss":"repetir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-02', 'lesson-pedagogy-a1-clarify', 2, 'sentence', 'Can you say that again?', 'Você pode dizer isso de novo?', '/kæn juː seɪ ðæt əˈɡɛn/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-03', 'lesson-pedagogy-a1-clarify', 3, 'sentence', 'Please speak slowly.', 'Por favor, fale devagar.', '/pliːz spiːk ˈsloʊli/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"slowly","pos":"adverb","ipa":"/ˈsloʊli/","gloss":"devagar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-04', 'lesson-pedagogy-a1-clarify', 4, 'sentence', 'I don''t understand.', 'Eu não entendo.', '/aɪ doʊnt ˌʌndərˈstænd/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"understand","pos":"verb","ipa":"/ˌʌndərˈstænd/","gloss":"entender"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-05', 'lesson-pedagogy-a1-clarify', 5, 'sentence', 'What does this mean?', 'O que isso significa?', '/wʌt dʌz ðɪs miːn/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-06', 'lesson-pedagogy-a1-clarify', 6, 'sentence', 'How do you spell your name?', 'Como se escreve seu nome?', '/haʊ duː juː spɛl jʊr neɪm/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"spell","pos":"verb","ipa":"/spɛl/","gloss":"soletrar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-07', 'lesson-pedagogy-a1-clarify', 7, 'sentence', 'Can you help me?', 'Você pode me ajudar?', '/kæn juː hɛlp miː/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-clarify-08', 'lesson-pedagogy-a1-clarify', 8, 'sentence', 'Thank you for your help.', 'Obrigado pela sua ajuda.', '/θæŋk juː fɔːr jʊr hɛlp/', 'Use estas fórmulas para pedir ajuda durante uma conversa. “Please” torna o pedido educado; “mean” pergunta o significado.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-articles-01', 'lesson-pedagogy-a1-articles', 1, 'sentence', 'This is a book.', 'Isto é um livro.', '/ðɪs ɪz ə bʊk/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-02', 'lesson-pedagogy-a1-articles', 2, 'sentence', 'I have an apple.', 'Eu tenho uma maçã.', '/aɪ hæv ən ˈæpəl/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"apple","pos":"noun","ipa":"/ˈæpəl/","gloss":"maçã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-03', 'lesson-pedagogy-a1-articles', 3, 'sentence', 'She is a teacher.', 'Ela é professora.', '/ʃiː ɪz ə ˈtiːtʃər/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"teacher","pos":"noun","ipa":"/ˈtiːtʃər/","gloss":"professor, professora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-04', 'lesson-pedagogy-a1-articles', 4, 'sentence', 'He is an actor.', 'Ele é ator.', '/hiː ɪz ən ˈæktər/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"actor","pos":"noun","ipa":"/ˈæktər/","gloss":"ator"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-05', 'lesson-pedagogy-a1-articles', 5, 'sentence', 'There is a cup on the table.', 'Há uma xícara na mesa.', '/ðɛr ɪz ə kʌp ɑːn ðə ˈteɪbəl/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"cup","pos":"noun","ipa":"/kʌp/","gloss":"xícara"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"table","pos":"noun","ipa":"/ˈteɪbəl/","gloss":"mesa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-06', 'lesson-pedagogy-a1-articles', 6, 'sentence', 'The cup is blue.', 'A xícara é azul.', '/ðə kʌp ɪz bluː/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cup","pos":"noun","ipa":"/kʌp/","gloss":"xícara"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-07', 'lesson-pedagogy-a1-articles', 7, 'sentence', 'I need a pen.', 'Eu preciso de uma caneta.', '/aɪ niːd ə pɛn/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pen","pos":"noun","ipa":"/pɛn/","gloss":"caneta"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-articles-08', 'lesson-pedagogy-a1-articles', 8, 'sentence', 'The pen is in my bag.', 'A caneta está na minha bolsa.', '/ðə pɛn ɪz ɪn maɪ bæɡ/', '“A/an” apresenta um elemento; “the” aponta algo identificado. A escolha entre “a” e “an” depende do som seguinte.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"pen","pos":"noun","ipa":"/pɛn/","gloss":"caneta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-plurals-01', 'lesson-pedagogy-a1-plurals', 1, 'sentence', 'I have two books.', 'Eu tenho dois livros.', '/aɪ hæv tuː bʊks/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"books","pos":"noun","ipa":"/bʊks/","gloss":"livros"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-02', 'lesson-pedagogy-a1-plurals', 2, 'sentence', 'There are three chairs.', 'Há três cadeiras.', '/ðɛr ɑːr θriː tʃɛrz/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"chairs","pos":"noun","ipa":"/tʃɛrz/","gloss":"cadeiras"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-03', 'lesson-pedagogy-a1-plurals', 3, 'sentence', 'These are my friends.', 'Estes são meus amigos.', '/ðiːz ɑːr maɪ frɛndz/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-04', 'lesson-pedagogy-a1-plurals', 4, 'sentence', 'The boxes are empty.', 'As caixas estão vazias.', '/ðə ˈbɑːksɪz ɑːr ˈɛmpti/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"boxes","pos":"noun","ipa":"/ˈbɑːksɪz/","gloss":"caixas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"empty","pos":"adjective","ipa":"/ˈɛmpti/","gloss":"vazio"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-05', 'lesson-pedagogy-a1-plurals', 5, 'sentence', 'She has two children.', 'Ela tem dois filhos.', '/ʃiː hæz tuː ˈtʃɪldrən/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-06', 'lesson-pedagogy-a1-plurals', 6, 'sentence', 'There are five people here.', 'Há cinco pessoas aqui.', '/ðɛr ɑːr faɪv ˈpiːpəl hɪr/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-07', 'lesson-pedagogy-a1-plurals', 7, 'sentence', 'The bus is outside.', 'O ônibus está lá fora.', '/ðə bʌs ɪz ˌaʊtˈsaɪd/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-plurals-08', 'lesson-pedagogy-a1-plurals', 8, 'sentence', 'The buses are outside.', 'Os ônibus estão lá fora.', '/ðə ˈbʌsɪz ɑːr ˌaʊtˈsaɪd/', 'Use o plural para mais de um elemento. Muitos nomes recebem “-s”; “children” e “people” são formas irregulares frequentes.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"buses","pos":"noun","ipa":"/ˈbʌsɪz/","gloss":"ônibus (plural)"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-demonstratives-01', 'lesson-pedagogy-a1-demonstratives', 1, 'sentence', 'This is my phone.', 'Este é meu telefone.', '/ðɪs ɪz maɪ foʊn/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-02', 'lesson-pedagogy-a1-demonstratives', 2, 'sentence', 'That is your bag.', 'Aquela é sua bolsa.', '/ðæt ɪz jʊr bæɡ/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-03', 'lesson-pedagogy-a1-demonstratives', 3, 'sentence', 'These are my keys.', 'Estas são minhas chaves.', '/ðiːz ɑːr maɪ kiːz/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-04', 'lesson-pedagogy-a1-demonstratives', 4, 'sentence', 'Those are her shoes.', 'Aqueles são os sapatos dela.', '/ðoʊz ɑːr hɜːr ʃuːz/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"Those","pos":"determiner","ipa":"/ðoʊz/","gloss":"aqueles, essas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"shoes","pos":"noun","ipa":"/ʃuːz/","gloss":"sapatos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-05', 'lesson-pedagogy-a1-demonstratives', 5, 'sentence', 'Is this your book?', 'Este livro é seu?', '/ɪz ðɪs jʊr bʊk/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-06', 'lesson-pedagogy-a1-demonstratives', 6, 'sentence', 'Are these your glasses?', 'Estes óculos são seus?', '/ɑːr ðiːz jʊr ˈɡlæsɪz/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"these","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"glasses","pos":"noun","ipa":"/ˈɡlæsɪz/","gloss":"óculos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-07', 'lesson-pedagogy-a1-demonstratives', 7, 'sentence', 'That chair is free.', 'Aquela cadeira está livre.', '/ðæt tʃɛr ɪz friː/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"chair","pos":"noun","ipa":"/tʃɛr/","gloss":"cadeira"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-demonstratives-08', 'lesson-pedagogy-a1-demonstratives', 8, 'sentence', 'Those people are my friends.', 'Aquelas pessoas são meus amigos.', '/ðoʊz ˈpiːpəl ɑːr maɪ frɛndz/', '“This/these” indica proximidade; “that/those”, distância. “This/that” acompanha singular; “these/those”, plural.', '[]'::jsonb, '[{"surface":"Those","pos":"determiner","ipa":"/ðoʊz/","gloss":"aqueles, essas"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-have-01', 'lesson-pedagogy-a1-have', 1, 'sentence', 'I have a bike.', 'Eu tenho uma bicicleta.', '/aɪ hæv ə baɪk/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bike","pos":"noun","ipa":"/baɪk/","gloss":"bicicleta"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-02', 'lesson-pedagogy-a1-have', 2, 'sentence', 'She has a car.', 'Ela tem um carro.', '/ʃiː hæz ə kɑːr/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-03', 'lesson-pedagogy-a1-have', 3, 'sentence', 'We have two cats.', 'Nós temos dois gatos.', '/wiː hæv tuː kæts/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"cats","pos":"noun","ipa":"/kæts/","gloss":"gatos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-04', 'lesson-pedagogy-a1-have', 4, 'sentence', 'I don''t have a ticket.', 'Eu não tenho ingresso.', '/aɪ doʊnt hæv ə ˈtɪkɪt/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-05', 'lesson-pedagogy-a1-have', 5, 'sentence', 'He doesn''t have a phone.', 'Ele não tem telefone.', '/hiː ˈdʌzənt hæv ə foʊn/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-06', 'lesson-pedagogy-a1-have', 6, 'sentence', 'Do you have a pen?', 'Você tem uma caneta?', '/duː juː hæv ə pɛn/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pen","pos":"noun","ipa":"/pɛn/","gloss":"caneta"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-07', 'lesson-pedagogy-a1-have', 7, 'sentence', 'Does she have a brother?', 'Ela tem irmão?', '/dʌz ʃiː hæv ə ˈbrʌðər/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"Does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-have-08', 'lesson-pedagogy-a1-have', 8, 'sentence', 'I''ve got a new bag.', 'Eu tenho uma bolsa nova.', '/aɪv ɡɑːt ə nuː bæɡ/', '“Have/has” expressa posse. Com “does/doesn''t”, o verbo volta a “have”. “Have got” também é comum, sobretudo no inglês britânico.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-object-pronouns-01', 'lesson-pedagogy-a1-object-pronouns', 1, 'sentence', 'Please help me.', 'Por favor, me ajude.', '/pliːz hɛlp miː/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-02', 'lesson-pedagogy-a1-object-pronouns', 2, 'sentence', 'I know him.', 'Eu conheço ele.', '/aɪ noʊ hɪm/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"him","pos":"pronoun","ipa":"/hɪm/","gloss":"ele, o, lhe"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-03', 'lesson-pedagogy-a1-object-pronouns', 3, 'sentence', 'Can you call her?', 'Você pode ligar para ela?', '/kæn juː kɔːl hɜːr/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-04', 'lesson-pedagogy-a1-object-pronouns', 4, 'sentence', 'Come with us.', 'Venha conosco.', '/kʌm wɪð ʌs/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"Come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-05', 'lesson-pedagogy-a1-object-pronouns', 5, 'sentence', 'I can see them.', 'Eu consigo ver eles.', '/aɪ kæn siː ðɛm/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-06', 'lesson-pedagogy-a1-object-pronouns', 6, 'sentence', 'She likes you.', 'Ela gosta de você.', '/ʃiː laɪks juː/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"likes","pos":"verb","ipa":"/laɪks/","gloss":"gosta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-07', 'lesson-pedagogy-a1-object-pronouns', 7, 'sentence', 'This is for me.', 'Isto é para mim.', '/ðɪs ɪz fɔːr miː/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-object-pronouns-08', 'lesson-pedagogy-a1-object-pronouns', 8, 'sentence', 'We need it today.', 'Nós precisamos disso hoje.', '/wiː niːd ɪt təˈdeɪ/', 'Pronomes de objeto recebem a ação ou vêm depois de preposições: “me”, “him”, “her”, “us” e “them”. “You” não muda.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-possessive-s-01', 'lesson-pedagogy-a1-possessive-s', 1, 'sentence', 'This is my sister''s bag.', 'Esta é a bolsa da minha irmã.', '/ðɪs ɪz maɪ ˈsɪstərz bæɡ/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"sister''s","pos":"noun","ipa":"/ˈsɪstərz/","gloss":"da irmã"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-02', 'lesson-pedagogy-a1-possessive-s', 2, 'sentence', 'That is my father''s car.', 'Aquele é o carro do meu pai.', '/ðæt ɪz maɪ ˈfɑːðərz kɑːr/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"father''s","pos":"noun","ipa":"/ˈfɑːðərz/","gloss":"do pai (possessivo)"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-03', 'lesson-pedagogy-a1-possessive-s', 3, 'sentence', 'My friend''s name is Ana.', 'O nome da minha amiga é Ana.', '/maɪ frɛndz neɪm ɪz ˈænə/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friend''s","pos":"noun","ipa":"/frɛndz/","gloss":"do amigo"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Ana","pos":"proper noun","ipa":"/ˈænə/","gloss":"Ana"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-04', 'lesson-pedagogy-a1-possessive-s', 4, 'sentence', 'Where is the teacher''s book?', 'Onde está o livro da professora?', '/wɛr ɪz ðə ˈtiːtʃərz bʊk/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"teacher''s","pos":"noun","ipa":"/ˈtiːtʃərz/","gloss":"da professora ou do professor (possessivo)"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-05', 'lesson-pedagogy-a1-possessive-s', 5, 'sentence', 'Is this your phone?', 'Este telefone é seu?', '/ɪz ðɪs jʊr foʊn/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-06', 'lesson-pedagogy-a1-possessive-s', 6, 'sentence', 'Yes, it''s mine.', 'Sim, é meu.', '/jɛs ɪts maɪn/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"mine","pos":"pronoun","ipa":"/maɪn/","gloss":"meu, minha (sem substantivo)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-07', 'lesson-pedagogy-a1-possessive-s', 7, 'sentence', 'This cup is yours.', 'Esta xícara é sua.', '/ðɪs kʌp ɪz jʊrz/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"cup","pos":"noun","ipa":"/kʌp/","gloss":"xícara"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"yours","pos":"pronoun","ipa":"/jʊrz/","gloss":"seu, o seu"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-possessive-s-08', 'lesson-pedagogy-a1-possessive-s', 8, 'sentence', 'Her brother''s room is small.', 'O quarto do irmão dela é pequeno.', '/hɜːr ˈbrʌðərz ruːm ɪz smɔːl/', 'O possessivo “''s” indica de quem é algo. “My/your” vem antes do nome; “mine/yours” substitui o nome quando já está claro.', '[]'::jsonb, '[{"surface":"Her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"brother''s","pos":"noun","ipa":"/ˈbrʌðərz/","gloss":"do irmão (possessivo)"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-descriptions-01', 'lesson-pedagogy-a1-descriptions', 1, 'sentence', 'My brother is tall.', 'Meu irmão é alto.', '/maɪ ˈbrʌðər ɪz tɔːl/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"tall","pos":"adjective","ipa":"/tɔːl/","gloss":"alto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-02', 'lesson-pedagogy-a1-descriptions', 2, 'sentence', 'She has short hair.', 'Ela tem cabelo curto.', '/ʃiː hæz ʃɔːrt hɛr/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"short","pos":"adjective","ipa":"/ʃɔːrt/","gloss":"curto"},{"surface":"hair","pos":"noun","ipa":"/hɛr/","gloss":"cabelo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-03', 'lesson-pedagogy-a1-descriptions', 3, 'sentence', 'This is a small room.', 'Este é um quarto pequeno.', '/ðɪs ɪz ə smɔːl ruːm/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-04', 'lesson-pedagogy-a1-descriptions', 4, 'sentence', 'Her car is red.', 'O carro dela é vermelho.', '/hɜːr kɑːr ɪz rɛd/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"Her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"red","pos":"adjective","ipa":"/rɛd/","gloss":"vermelho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-05', 'lesson-pedagogy-a1-descriptions', 5, 'sentence', 'He is twenty years old.', 'Ele tem vinte anos.', '/hiː ɪz ˈtwɛnti jɪrz oʊld/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"twenty","pos":"numeral","ipa":"/ˈtwɛnti/","gloss":"vinte"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-06', 'lesson-pedagogy-a1-descriptions', 6, 'sentence', 'The house is old.', 'A casa é antiga.', '/ðə haʊs ɪz oʊld/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"house","pos":"noun","ipa":"/haʊs/","gloss":"casa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-07', 'lesson-pedagogy-a1-descriptions', 7, 'sentence', 'I have a new phone.', 'Eu tenho um telefone novo.', '/aɪ hæv ə nuː foʊn/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-descriptions-08', 'lesson-pedagogy-a1-descriptions', 8, 'sentence', 'The children are happy.', 'As crianças estão felizes.', '/ðə ˈtʃɪldrən ɑːr ˈhæpi/', 'Adjetivos podem vir depois de “be” ou antes do substantivo. Para idade, use “be”, não “have”: “She is twenty”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"happy","pos":"adjective","ipa":"/ˈhæpi/","gloss":"feliz"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-frequency-01', 'lesson-pedagogy-a1-frequency', 1, 'sentence', 'I always eat breakfast.', 'Eu sempre tomo café da manhã.', '/aɪ ˈɔːlweɪz iːt ˈbrɛkfəst/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"always","pos":"adverb","ipa":"/ˈɔːlweɪz/","gloss":"sempre"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-02', 'lesson-pedagogy-a1-frequency', 2, 'sentence', 'She usually takes the bus.', 'Ela geralmente pega o ônibus.', '/ʃiː ˈjuːʒuəli teɪks ðə bʌs/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-03', 'lesson-pedagogy-a1-frequency', 3, 'sentence', 'We sometimes cook at home.', 'Às vezes nós cozinhamos em casa.', '/wiː ˈsʌmtaɪmz kʊk æt hoʊm/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"sometimes","pos":"adverb","ipa":"/ˈsʌmtaɪmz/","gloss":"às vezes"},{"surface":"cook","pos":"noun","ipa":"/kʊk/","gloss":"cozinheiro"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-04', 'lesson-pedagogy-a1-frequency', 4, 'sentence', 'He never drinks coffee.', 'Ele nunca toma café.', '/hiː ˈnɛvər drɪŋks ˈkɔːfi/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"drinks","pos":"verb","ipa":"/drɪŋks/","gloss":"bebe"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-05', 'lesson-pedagogy-a1-frequency', 5, 'sentence', 'I''m usually at home at night.', 'Geralmente estou em casa à noite.', '/aɪm ˈjuːʒuəli æt hoʊm æt naɪt/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-06', 'lesson-pedagogy-a1-frequency', 6, 'sentence', 'Do you often walk to work?', 'Você costuma ir a pé para o trabalho?', '/duː juː ˈɔːfən wɔːk tuː wɜːrk/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"often","pos":"adverb","ipa":"/ˈɔːfən/","gloss":"frequentemente"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-07', 'lesson-pedagogy-a1-frequency', 7, 'sentence', 'I study English every day.', 'Eu estudo inglês todos os dias.', '/aɪ ˈstʌdi ˈɪŋɡlɪʃ ˈɛvri deɪ/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-frequency-08', 'lesson-pedagogy-a1-frequency', 8, 'sentence', 'She doesn''t work on Sundays.', 'Ela não trabalha aos domingos.', '/ʃiː ˈdʌzənt wɜːrk ɑːn ˈsʌndeɪz/', 'Advérbios como “usually” vêm normalmente antes do verbo principal e depois de “be”. “Never” já tem sentido negativo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Sundays","pos":"proper noun","ipa":"/ˈsʌndeɪz/","gloss":"domingos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-some-any-01', 'lesson-pedagogy-a1-some-any', 1, 'sentence', 'There is some milk.', 'Há um pouco de leite.', '/ðɛr ɪz sʌm mɪlk/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-02', 'lesson-pedagogy-a1-some-any', 2, 'sentence', 'There isn''t any water.', 'Não há água.', '/ðɛr ˈɪzənt ˈɛni ˈwɔːtər/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-03', 'lesson-pedagogy-a1-some-any', 3, 'sentence', 'Do you have any bread?', 'Você tem pão?', '/duː juː hæv ˈɛni brɛd/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-04', 'lesson-pedagogy-a1-some-any', 4, 'sentence', 'I''d like some rice.', 'Eu gostaria de um pouco de arroz.', '/aɪd laɪk sʌm raɪs/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"rice","pos":"noun","ipa":"/raɪs/","gloss":"arroz"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-05', 'lesson-pedagogy-a1-some-any', 5, 'sentence', 'We have some apples.', 'Nós temos algumas maçãs.', '/wiː hæv sʌm ˈæpəlz/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"apples","pos":"noun","ipa":"/ˈæpəlz/","gloss":"maçãs"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-06', 'lesson-pedagogy-a1-some-any', 6, 'sentence', 'Are there any cups?', 'Há xícaras?', '/ɑːr ðɛr ˈɛni kʌps/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"cups","pos":"noun","ipa":"/kʌps/","gloss":"xícaras"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-07', 'lesson-pedagogy-a1-some-any', 7, 'sentence', 'Would you like some tea?', 'Você gostaria de um pouco de chá?', '/wʊd juː laɪk sʌm tiː/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"tea","pos":"noun","ipa":"/tiː/","gloss":"chá"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-some-any-08', 'lesson-pedagogy-a1-some-any', 8, 'sentence', 'I don''t have any money.', 'Eu não tenho dinheiro.', '/aɪ doʊnt hæv ˈɛni ˈmʌni/', '“Some” é comum em afirmações e ofertas; “any”, em perguntas neutras e negativas. Nesta aula, aprenda os padrões com comida e objetos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-basic-connectors-01', 'lesson-pedagogy-a1-basic-connectors', 1, 'sentence', 'I like tea and coffee.', 'Eu gosto de chá e café.', '/aɪ laɪk tiː ænd ˈkɔːfi/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"tea","pos":"noun","ipa":"/tiː/","gloss":"chá"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-02', 'lesson-pedagogy-a1-basic-connectors', 2, 'sentence', 'She is kind and friendly.', 'Ela é gentil e simpática.', '/ʃiː ɪz kaɪnd ænd ˈfrɛndli/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"kind","pos":"adjective","ipa":"/kaɪnd/","gloss":"gentil"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"friendly","pos":"adjective","ipa":"/ˈfrɛndli/","gloss":"simpático"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-03', 'lesson-pedagogy-a1-basic-connectors', 3, 'sentence', 'The room is small but nice.', 'O quarto é pequeno, mas agradável.', '/ðə ruːm ɪz smɔːl bʌt naɪs/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"nice","pos":"adjective","ipa":"/naɪs/","gloss":"prazer; legal"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-04', 'lesson-pedagogy-a1-basic-connectors', 4, 'sentence', 'I can swim, but I can''t drive.', 'Eu sei nadar, mas não sei dirigir.', '/aɪ kæn swɪm bʌt aɪ kænt draɪv/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-05', 'lesson-pedagogy-a1-basic-connectors', 5, 'sentence', 'I''m tired because I work at night.', 'Estou cansado porque trabalho à noite.', '/aɪm ˈtaɪərd bɪˈkɔːz aɪ wɜːrk æt naɪt/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-06', 'lesson-pedagogy-a1-basic-connectors', 6, 'sentence', 'I like this place because it''s quiet.', 'Eu gosto deste lugar porque é tranquilo.', '/aɪ laɪk ðɪs pleɪs bɪˈkɔːz ɪts ˈkwaɪət/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-07', 'lesson-pedagogy-a1-basic-connectors', 7, 'sentence', 'He cooks, and I clean.', 'Ele cozinha, e eu limpo.', '/hiː kʊks ænd aɪ kliːn/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"cooks","pos":"verb","ipa":"/kʊks/","gloss":"cozinha"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"clean","pos":"verb","ipa":"/kliːn/","gloss":"limpar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-basic-connectors-08', 'lesson-pedagogy-a1-basic-connectors', 8, 'sentence', 'We need food and water.', 'Nós precisamos de comida e água.', '/wiː niːd fuːd ænd ˈwɔːtər/', '“And” acrescenta informação, “but” contrasta e “because” dá uma razão. Use-os para unir ideias curtas que você já conhece.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a1-now-01', 'lesson-pedagogy-a1-now', 1, 'sentence', 'I''m reading a book.', 'Estou lendo um livro.', '/aɪm ˈriːdɪŋ ə bʊk/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"reading","pos":"noun","ipa":"/ˈriːdɪŋ/","gloss":"leitura"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-02', 'lesson-pedagogy-a1-now', 2, 'sentence', 'She is cooking dinner.', 'Ela está preparando o jantar.', '/ʃiː ɪz ˈkʊkɪŋ ˈdɪnər/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cooking","pos":"verb","ipa":"/ˈkʊkɪŋ/","gloss":"cozinhar (atividade)"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-03', 'lesson-pedagogy-a1-now', 3, 'sentence', 'They are playing outside.', 'Eles estão brincando lá fora.', '/ðeɪ ɑːr ˈpleɪɪŋ ˌaʊtˈsaɪd/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"playing","pos":"verb","ipa":"/ˈpleɪɪŋ/","gloss":"jogando, brincando"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-04', 'lesson-pedagogy-a1-now', 4, 'sentence', 'We aren''t working now.', 'Não estamos trabalhando agora.', '/wiː ɑːrnt ˈwɜːrkɪŋ naʊ/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-05', 'lesson-pedagogy-a1-now', 5, 'sentence', 'He isn''t sleeping.', 'Ele não está dormindo.', '/hiː ˈɪzənt ˈsliːpɪŋ/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"sleeping","pos":"verb","ipa":"/ˈsliːpɪŋ/","gloss":"dormindo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-06', 'lesson-pedagogy-a1-now', 6, 'sentence', 'Are you listening?', 'Você está ouvindo?', '/ɑːr juː ˈlɪsənɪŋ/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"listening","pos":"verb","ipa":"/ˈlɪsənɪŋ/","gloss":"ouvindo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-07', 'lesson-pedagogy-a1-now', 7, 'sentence', 'What are you doing?', 'O que você está fazendo?', '/wʌt ɑːr juː ˈduːɪŋ/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"doing","pos":"verb","ipa":"/ˈduːɪŋ/","gloss":"fazendo, fazer"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a1-now-08', 'lesson-pedagogy-a1-now', 8, 'sentence', 'It''s raining.', 'Está chovendo.', '/ɪts ˈreɪnɪŋ/', 'Para uma ação em andamento agora, use “am/is/are” + verbo com “-ing”. Na pergunta, “am/is/are” vem antes do sujeito.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"raining","pos":"verb","ipa":"/ˈreɪnɪŋ/","gloss":"chovendo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-past-simple-01', 'lesson-pedagogy-a2-past-simple', 1, 'sentence', 'I visited my sister yesterday.', 'Eu visitei minha irmã ontem.', '/aɪ ˈvɪzɪtɪd maɪ ˈsɪstər ˈjɛstərdeɪ/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"visited","pos":"verb","ipa":"/ˈvɪzɪtɪd/","gloss":"visitou"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-02', 'lesson-pedagogy-a2-past-simple', 2, 'sentence', 'She worked last Saturday.', 'Ela trabalhou no sábado passado.', '/ʃiː wɜːrkt læst ˈsætərdeɪ/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"Saturday","pos":"proper noun","ipa":"/ˈsætərdeɪ/","gloss":"sábado"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-03', 'lesson-pedagogy-a2-past-simple', 3, 'sentence', 'We went to the beach.', 'Nós fomos à praia.', '/wiː wɛnt tuː ðə biːtʃ/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beach","pos":"noun","ipa":"/biːtʃ/","gloss":"praia"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-04', 'lesson-pedagogy-a2-past-simple', 4, 'sentence', 'He bought a new phone.', 'Ele comprou um telefone novo.', '/hiː bɔːt ə nuː foʊn/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-05', 'lesson-pedagogy-a2-past-simple', 5, 'sentence', 'I didn''t see the message.', 'Eu não vi a mensagem.', '/aɪ ˈdɪdənt siː ðə ˈmɛsɪdʒ/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-06', 'lesson-pedagogy-a2-past-simple', 6, 'sentence', 'Did you call your mother?', 'Você ligou para sua mãe?', '/dɪd juː kɔːl jʊr ˈmʌðər/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-07', 'lesson-pedagogy-a2-past-simple', 7, 'sentence', 'Where did they go?', 'Aonde eles foram?', '/wɛr dɪd ðeɪ ɡoʊ/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-past-simple-08', 'lesson-pedagogy-a2-past-simple', 8, 'sentence', 'We didn''t have time.', 'Nós não tivemos tempo.', '/wiː ˈdɪdənt hæv taɪm/', 'Para eventos concluídos, use o passado. Em perguntas e negativas com “did/didn''t”, o verbo fica na base: “Did you go?”.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-comparatives-01', 'lesson-pedagogy-a2-comparatives', 1, 'sentence', 'This room is bigger than mine.', 'Este quarto é maior que o meu.', '/ðɪs ruːm ɪz ˈbɪɡər ðæn maɪn/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"bigger","pos":"adjective","ipa":"/ˈbɪɡər/","gloss":"maior"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"mine","pos":"pronoun","ipa":"/maɪn/","gloss":"meu, minha (sem substantivo)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-02', 'lesson-pedagogy-a2-comparatives', 2, 'sentence', 'My bag is smaller than yours.', 'Minha bolsa é menor que a sua.', '/maɪ bæɡ ɪz ˈsmɔːlər ðæn jʊrz/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"smaller","pos":"adjective","ipa":"/ˈsmɔːlər/","gloss":"menor"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"yours","pos":"pronoun","ipa":"/jʊrz/","gloss":"seu, o seu"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-03', 'lesson-pedagogy-a2-comparatives', 3, 'sentence', 'This one is cheaper.', 'Este aqui é mais barato.', '/ðɪs wʌn ɪz ˈtʃiːpər/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cheaper","pos":"adjective","ipa":"/ˈtʃiːpər/","gloss":"mais barato"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-04', 'lesson-pedagogy-a2-comparatives', 4, 'sentence', 'The blue shirt is more expensive.', 'A camisa azul é mais cara.', '/ðə bluː ʃɜːrt ɪz mɔːr ɪkˈspɛnsɪv/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"},{"surface":"shirt","pos":"noun","ipa":"/ʃɜːrt/","gloss":"camisa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-05', 'lesson-pedagogy-a2-comparatives', 5, 'sentence', 'The train is faster than the bus.', 'O trem é mais rápido que o ônibus.', '/ðə treɪn ɪz ˈfæstər ðæn ðə bʌs/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"faster","pos":"adjective","ipa":"/ˈfæstər/","gloss":"mais rápido"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-06', 'lesson-pedagogy-a2-comparatives', 6, 'sentence', 'This route is easier.', 'Este caminho é mais fácil.', '/ðɪs ruːt ɪz ˈiːziər/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"route","pos":"noun","ipa":"/ruːt/","gloss":"rota, caminho"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"easier","pos":"adjective","ipa":"/ˈiːziər/","gloss":"mais fácil"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-07', 'lesson-pedagogy-a2-comparatives', 7, 'sentence', 'The weather is better today.', 'O tempo está melhor hoje.', '/ðə ˈwɛðər ɪz ˈbɛtər təˈdeɪ/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weather","pos":"noun","ipa":"/ˈwɛðər/","gloss":"tempo, clima"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-comparatives-08', 'lesson-pedagogy-a2-comparatives', 8, 'sentence', 'This coffee is worse than the other one.', 'Este café é pior que o outro.', '/ðɪs ˈkɔːfi ɪz wɜːrs ðæn ðə ˈʌðər wʌn/', 'Comparativos usam “-er” ou “more”; “than” introduz a comparação. “Better/worse” são formas irregulares de “good/bad”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"worse","pos":"adjective","ipa":"/wɜːrs/","gloss":"pior"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"other","pos":"pronoun","ipa":"/ˈʌðər/","gloss":"outro"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-superlatives-01', 'lesson-pedagogy-a2-superlatives', 1, 'sentence', 'This is the cheapest option.', 'Esta é a opção mais barata.', '/ðɪs ɪz ðə ˈtʃiːpɪst ˈɑːpʃən/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cheapest","pos":"adjective","ipa":"/ˈtʃiːpɪst/","gloss":"mais barato"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-02', 'lesson-pedagogy-a2-superlatives', 2, 'sentence', 'She is the tallest person here.', 'Ela é a pessoa mais alta aqui.', '/ʃiː ɪz ðə ˈtɔːlɪst ˈpɜːrsən hɪr/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tallest","pos":"adjective","ipa":"/ˈtɔːlɪst/","gloss":"mais alto"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-03', 'lesson-pedagogy-a2-superlatives', 3, 'sentence', 'This is the smallest room.', 'Este é o menor quarto.', '/ðɪs ɪz ðə ˈsmɔːlɪst ruːm/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"smallest","pos":"adjective","ipa":"/ˈsmɔːlɪst/","gloss":"menor"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-04', 'lesson-pedagogy-a2-superlatives', 4, 'sentence', 'It is the most expensive hotel.', 'É o hotel mais caro.', '/ɪt ɪz ðə moʊst ɪkˈspɛnsɪv hoʊˈtɛl/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-05', 'lesson-pedagogy-a2-superlatives', 5, 'sentence', 'That was the best part.', 'Aquela foi a melhor parte.', '/ðæt wɑːz ðə bɛst pɑːrt/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"part","pos":"noun","ipa":"/pɑːrt/","gloss":"parte"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-06', 'lesson-pedagogy-a2-superlatives', 6, 'sentence', 'This is the worst seat.', 'Este é o pior lugar para sentar.', '/ðɪs ɪz ðə wɜːrst siːt/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"worst","pos":"adjective","ipa":"/wɜːrst/","gloss":"pior"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-07', 'lesson-pedagogy-a2-superlatives', 7, 'sentence', 'Which is the fastest train?', 'Qual é o trem mais rápido?', '/wɪtʃ ɪz ðə ˈfæstɪst treɪn/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"Which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"fastest","pos":"adjective","ipa":"/ˈfæstɪst/","gloss":"o mais rápido"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-superlatives-08', 'lesson-pedagogy-a2-superlatives', 8, 'sentence', 'Monday is my busiest day.', 'Segunda-feira é meu dia mais corrido.', '/ˈmʌndeɪ ɪz maɪ ˈbɪziɪst deɪ/', 'Para destacar um elemento de um grupo, use normalmente “the” + superlativo: “the biggest”, “the most expensive”, “the best”.', '[]'::jsonb, '[{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"busiest","pos":"adjective","ipa":"/ˈbɪziɪst/","gloss":"mais ocupado"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-countability-01', 'lesson-pedagogy-a2-countability', 1, 'sentence', 'How many apples do we need?', 'De quantas maçãs precisamos?', '/haʊ ˈmɛni ˈæpəlz duː wiː niːd/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"apples","pos":"noun","ipa":"/ˈæpəlz/","gloss":"maçãs"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-02', 'lesson-pedagogy-a2-countability', 2, 'sentence', 'How much water do you drink?', 'Quanta água você bebe?', '/haʊ mʌtʃ ˈwɔːtər duː juː drɪŋk/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-03', 'lesson-pedagogy-a2-countability', 3, 'sentence', 'We don''t have much time.', 'Nós não temos muito tempo.', '/wiː doʊnt hæv mʌtʃ taɪm/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-04', 'lesson-pedagogy-a2-countability', 4, 'sentence', 'There aren''t many chairs.', 'Não há muitas cadeiras.', '/ðɛr ɑːrnt ˈmɛni tʃɛrz/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"aren''t","pos":"verb","ipa":"/ɑːrnt/","gloss":"não são, não estão (are not)"},{"surface":"many","pos":"determiner","ipa":"/ˈmɛni/","gloss":"muitos (how many)"},{"surface":"chairs","pos":"noun","ipa":"/tʃɛrz/","gloss":"cadeiras"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-05', 'lesson-pedagogy-a2-countability', 5, 'sentence', 'I have a lot of books.', 'Eu tenho muitos livros.', '/aɪ hæv ə lɑːt ʌv bʊks/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"books","pos":"noun","ipa":"/bʊks/","gloss":"livros"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-06', 'lesson-pedagogy-a2-countability', 6, 'sentence', 'She drinks a lot of coffee.', 'Ela toma muito café.', '/ʃiː drɪŋks ə lɑːt ʌv ˈkɔːfi/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"drinks","pos":"verb","ipa":"/drɪŋks/","gloss":"bebe"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-07', 'lesson-pedagogy-a2-countability', 7, 'sentence', 'Can I have some bread?', 'Posso comer um pouco de pão?', '/kæn aɪ hæv sʌm brɛd/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"bread","pos":"noun","ipa":"/brɛd/","gloss":"pão"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-countability-08', 'lesson-pedagogy-a2-countability', 8, 'sentence', 'We don''t need any rice.', 'Nós não precisamos de arroz.', '/wiː doʊnt niːd ˈɛni raɪs/', '“Many” acompanha nomes contáveis no plural; “much” acompanha incontáveis. “A lot of” funciona nos dois casos. Não pluralize “water” ou “rice” nestes sentidos.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"rice","pos":"noun","ipa":"/raɪs/","gloss":"arroz"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-too-enough-01', 'lesson-pedagogy-a2-too-enough', 1, 'sentence', 'This shirt is too small.', 'Esta camisa é pequena demais.', '/ðɪs ʃɜːrt ɪz tuː smɔːl/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"shirt","pos":"noun","ipa":"/ʃɜːrt/","gloss":"camisa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-02', 'lesson-pedagogy-a2-too-enough', 2, 'sentence', 'The bag is big enough.', 'A bolsa é grande o suficiente.', '/ðə bæɡ ɪz bɪɡ ɪˈnʌf/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bag","pos":"noun","ipa":"/bæɡ/","gloss":"mala, bolsa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-03', 'lesson-pedagogy-a2-too-enough', 3, 'sentence', 'We have enough time.', 'Nós temos tempo suficiente.', '/wiː hæv ɪˈnʌf taɪm/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-04', 'lesson-pedagogy-a2-too-enough', 4, 'sentence', 'There isn''t enough milk.', 'Não há leite suficiente.', '/ðɛr ˈɪzənt ɪˈnʌf mɪlk/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-05', 'lesson-pedagogy-a2-too-enough', 5, 'sentence', 'I have a few questions.', 'Eu tenho algumas perguntas.', '/aɪ hæv ə fjuː ˈkwɛstʃənz/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"few","pos":"determiner","ipa":"/fjuː/","gloss":"poucos"},{"surface":"questions","pos":"noun","ipa":"/ˈkwɛstʃənz/","gloss":"perguntas, dúvidas"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-06', 'lesson-pedagogy-a2-too-enough', 6, 'sentence', 'Add a little water.', 'Adicione um pouco de água.', '/æd ə ˈlɪtəl ˈwɔːtər/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"Add","pos":"verb","ipa":"/æd/","gloss":"acrescentar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-07', 'lesson-pedagogy-a2-too-enough', 7, 'sentence', 'It''s too cold to swim.', 'Está frio demais para nadar.', '/ɪts tuː koʊld tuː swɪm/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"swim","pos":"verb","ipa":"/swɪm/","gloss":"nadar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-too-enough-08', 'lesson-pedagogy-a2-too-enough', 8, 'sentence', 'We don''t have enough chairs.', 'Nós não temos cadeiras suficientes.', '/wiː doʊnt hæv ɪˈnʌf tʃɛrz/', '“Too” indica excesso; “enough”, quantidade suficiente. “A few” acompanha contáveis; “a little”, incontáveis. Compare “big enough” e “enough time”.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"},{"surface":"chairs","pos":"noun","ipa":"/tʃɛrz/","gloss":"cadeiras"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-advice-rules-01', 'lesson-pedagogy-a2-advice-rules', 1, 'sentence', 'You should take a break.', 'Você deveria fazer uma pausa.', '/juː ʃʊd teɪk ə breɪk/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"break","pos":"noun","ipa":"/breɪk/","gloss":"pausa, intervalo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-02', 'lesson-pedagogy-a2-advice-rules', 2, 'sentence', 'You shouldn''t drive so fast.', 'Você não deveria dirigir tão rápido.', '/juː ˈʃʊdənt draɪv soʊ fæst/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"shouldn''t","pos":"verb","ipa":"/ˈʃʊdənt/","gloss":"não deveria (should not)"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"fast","pos":"adverb","ipa":"/fæst/","gloss":"rápido"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-03', 'lesson-pedagogy-a2-advice-rules', 3, 'sentence', 'Should I call her?', 'Eu deveria ligar para ela?', '/ʃʊd aɪ kɔːl hɜːr/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"Should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-04', 'lesson-pedagogy-a2-advice-rules', 4, 'sentence', 'You must wear a seatbelt.', 'Você deve usar cinto de segurança.', '/juː mʌst wɛr ə ˈsiːtbɛlt/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"wear","pos":"verb","ipa":"/wɛr/","gloss":"usar, vestir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"seatbelt","pos":"noun","ipa":"/ˈsiːtbɛlt/","gloss":"cinto de segurança"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-05', 'lesson-pedagogy-a2-advice-rules', 5, 'sentence', 'You mustn''t park here.', 'É proibido estacionar aqui.', '/juː ˈmʌsənt pɑːrk hɪr/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mustn''t","pos":"verb","ipa":"/ˈmʌsənt/","gloss":"não pode (must not)"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-06', 'lesson-pedagogy-a2-advice-rules', 6, 'sentence', 'You don''t have to come early.', 'Você não precisa chegar cedo.', '/juː doʊnt hæv tuː kʌm ˈɜːrli/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-07', 'lesson-pedagogy-a2-advice-rules', 7, 'sentence', 'I have to work tomorrow.', 'Eu tenho que trabalhar amanhã.', '/aɪ hæv tuː wɜːrk təˈmɑːroʊ/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-advice-rules-08', 'lesson-pedagogy-a2-advice-rules', 8, 'sentence', 'Do we have to pay now?', 'Nós temos que pagar agora?', '/duː wiː hæv tuː peɪ naʊ/', '“Should” dá conselho; “mustn''t” proíbe; “don''t have to” indica que algo não é obrigatório. Depois do modal, use o verbo base.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-simple-conditionals-01', 'lesson-pedagogy-a2-simple-conditionals', 1, 'sentence', 'If it rains, I''ll stay home.', 'Se chover, vou ficar em casa.', '/ɪf ɪt reɪnz aɪl steɪ hoʊm/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-02', 'lesson-pedagogy-a2-simple-conditionals', 2, 'sentence', 'If you''re hungry, eat something.', 'Se estiver com fome, coma alguma coisa.', '/ɪf jʊr ˈhʌŋɡri iːt ˈsʌmθɪŋ/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you''re","pos":"pronoun","ipa":"/jʊr/","gloss":"você está, você é"},{"surface":"hungry","pos":"adjective","ipa":"/ˈhʌŋɡri/","gloss":"com fome"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"},{"surface":"something","pos":"pronoun","ipa":"/ˈsʌmθɪŋ/","gloss":"alguma coisa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-03', 'lesson-pedagogy-a2-simple-conditionals', 3, 'sentence', 'I''ll call you if I''m late.', 'Vou te ligar se eu me atrasar.', '/aɪl kɔːl juː ɪf aɪm leɪt/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-04', 'lesson-pedagogy-a2-simple-conditionals', 4, 'sentence', 'If we leave now, we''ll arrive on time.', 'Se sairmos agora, chegaremos a tempo.', '/ɪf wiː liːv naʊ wiːl əˈraɪv ɑːn taɪm/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-05', 'lesson-pedagogy-a2-simple-conditionals', 5, 'sentence', 'If I drink coffee at night, I don''t sleep well.', 'Se tomo café à noite, não durmo bem.', '/ɪf aɪ drɪŋk ˈkɔːfi æt naɪt aɪ doʊnt sliːp wɛl/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-06', 'lesson-pedagogy-a2-simple-conditionals', 6, 'sentence', 'If the store is closed, we''ll come back tomorrow.', 'Se a loja estiver fechada, voltaremos amanhã.', '/ɪf ðə stɔːr ɪz kloʊzd wiːl kʌm bæk təˈmɑːroʊ/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-07', 'lesson-pedagogy-a2-simple-conditionals', 7, 'sentence', 'What will you do if it rains?', 'O que você vai fazer se chover?', '/wʌt wɪl juː duː ɪf ɪt reɪnz/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-simple-conditionals-08', 'lesson-pedagogy-a2-simple-conditionals', 8, 'sentence', 'If you need help, ask me.', 'Se precisar de ajuda, me peça.', '/ɪf juː niːd hɛlp æsk miː/', 'Na condição com “if”, use presente simples. Para uma consequência futura, “will” normalmente vem na outra parte; hábitos podem usar presente nas duas partes.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-verb-patterns-01', 'lesson-pedagogy-a2-verb-patterns', 1, 'sentence', 'I want to learn English.', 'Eu quero aprender inglês.', '/aɪ wɑːnt tuː lɜːrn ˈɪŋɡlɪʃ/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"learn","pos":"verb","ipa":"/lɜːrn/","gloss":"aprender"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-02', 'lesson-pedagogy-a2-verb-patterns', 2, 'sentence', 'She needs to leave early.', 'Ela precisa sair cedo.', '/ʃiː niːdz tuː liːv ˈɜːrli/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"needs","pos":"verb","ipa":"/niːdz/","gloss":"precisa"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-03', 'lesson-pedagogy-a2-verb-patterns', 3, 'sentence', 'We''d like to book a room.', 'Gostaríamos de reservar um quarto.', '/wiːd laɪk tuː bʊk ə ruːm/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"We''d","pos":"verb","ipa":"/wiːd/","gloss":"nós gostaríamos; nós tínhamos (we would/had)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-04', 'lesson-pedagogy-a2-verb-patterns', 4, 'sentence', 'I enjoy cooking.', 'Eu gosto de cozinhar.', '/aɪ ɪnˈdʒɔɪ ˈkʊkɪŋ/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"cooking","pos":"verb","ipa":"/ˈkʊkɪŋ/","gloss":"cozinhar (atividade)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-05', 'lesson-pedagogy-a2-verb-patterns', 5, 'sentence', 'He likes playing football.', 'Ele gosta de jogar futebol.', '/hiː laɪks ˈpleɪɪŋ ˈfʊtbɔːl/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"likes","pos":"verb","ipa":"/laɪks/","gloss":"gosta"},{"surface":"playing","pos":"verb","ipa":"/ˈpleɪɪŋ/","gloss":"jogando, brincando"},{"surface":"football","pos":"noun","ipa":"/ˈfʊtbɔːl/","gloss":"futebol"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-06', 'lesson-pedagogy-a2-verb-patterns', 6, 'sentence', 'Do you want to come with us?', 'Você quer vir conosco?', '/duː juː wɑːnt tuː kʌm wɪð ʌs/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-07', 'lesson-pedagogy-a2-verb-patterns', 7, 'sentence', 'She decided to stay.', 'Ela decidiu ficar.', '/ʃiː dɪˈsaɪdɪd tuː steɪ/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"decided","pos":"verb","ipa":"/dɪˈsaɪdɪd/","gloss":"decidiu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"stay","pos":"verb","ipa":"/steɪ/","gloss":"ficar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-verb-patterns-08', 'lesson-pedagogy-a2-verb-patterns', 8, 'sentence', 'I don''t enjoy waiting.', 'Eu não gosto de esperar.', '/aɪ doʊnt ɪnˈdʒɔɪ ˈweɪtɪŋ/', 'Aprenda a combinação com cada verbo: “want/need/decide” + “to”; “enjoy” + “-ing”. Não aplique uma única regra a todos os verbos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"enjoy","pos":"verb","ipa":"/ɪnˈdʒɔɪ/","gloss":"aproveitar"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-purpose-sequence-01', 'lesson-pedagogy-a2-purpose-sequence', 1, 'sentence', 'I went to the store to buy milk.', 'Fui à loja para comprar leite.', '/aɪ wɛnt tuː ðə stɔːr tuː baɪ mɪlk/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-02', 'lesson-pedagogy-a2-purpose-sequence', 2, 'sentence', 'She called to ask a question.', 'Ela ligou para fazer uma pergunta.', '/ʃiː kɔːld tuː æsk ə ˈkwɛstʃən/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"ask","pos":"verb","ipa":"/æsk/","gloss":"perguntar, pedir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-03', 'lesson-pedagogy-a2-purpose-sequence', 3, 'sentence', 'We use this app to study English.', 'Nós usamos este aplicativo para estudar inglês.', '/wiː juːz ðɪs æp tuː ˈstʌdi ˈɪŋɡlɪʃ/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"app","pos":"noun","ipa":"/æp/","gloss":"aplicativo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-04', 'lesson-pedagogy-a2-purpose-sequence', 4, 'sentence', 'I wash my hands before I eat.', 'Eu lavo as mãos antes de comer.', '/aɪ wɑːʃ maɪ hændz bɪˈfɔːr aɪ iːt/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wash","pos":"verb","ipa":"/wɑːʃ/","gloss":"lavar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"hands","pos":"noun","ipa":"/hændz/","gloss":"mãos"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"eat","pos":"verb","ipa":"/iːt/","gloss":"comer"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-05', 'lesson-pedagogy-a2-purpose-sequence', 5, 'sentence', 'We had coffee after lunch.', 'Tomamos café depois do almoço.', '/wiː hæd ˈkɔːfi ˈæftər lʌntʃ/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-06', 'lesson-pedagogy-a2-purpose-sequence', 6, 'sentence', 'Call me when you arrive.', 'Me ligue quando chegar.', '/kɔːl miː wɛn juː əˈraɪv/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"Call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"when","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-07', 'lesson-pedagogy-a2-purpose-sequence', 7, 'sentence', 'I need a pen to write this down.', 'Preciso de uma caneta para anotar isto.', '/aɪ niːd ə pɛn tuː raɪt ðɪs daʊn/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"pen","pos":"noun","ipa":"/pɛn/","gloss":"caneta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"write","pos":"verb","ipa":"/raɪt/","gloss":"escrever"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-purpose-sequence-08', 'lesson-pedagogy-a2-purpose-sequence', 8, 'sentence', 'After dinner, we watched a film.', 'Depois do jantar, assistimos a um filme.', '/ˈæftər ˈdɪnər wiː wɑːtʃt ə fɪlm/', '“To” + verbo explica a finalidade. “Before/after/when” relaciona momentos; use padrões simples antes de ampliar as orações.', '[]'::jsonb, '[{"surface":"After","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"watched","pos":"verb","ipa":"/wɑːtʃt/","gloss":"assistiu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-a2-recent-experiences-01', 'lesson-pedagogy-a2-recent-experiences', 1, 'sentence', 'Have you ever been to London?', 'Você já foi a Londres?', '/hæv juː ˈɛvər bɪn tuː ˈlʌndən/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ever","pos":"adverb","ipa":"/ˈɛvər/","gloss":"alguma vez, já"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"London","pos":"proper noun","ipa":"/ˈlʌndən/","gloss":"Londres"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-02', 'lesson-pedagogy-a2-recent-experiences', 2, 'sentence', 'I''ve never tried this food.', 'Eu nunca experimentei esta comida.', '/aɪv ˈnɛvər traɪd ðɪs fuːd/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"never","pos":"adverb","ipa":"/ˈnɛvər/","gloss":"nunca"},{"surface":"tried","pos":"verb","ipa":"/traɪd/","gloss":"tentou, experimentou"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"food","pos":"noun","ipa":"/fuːd/","gloss":"comida"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-03', 'lesson-pedagogy-a2-recent-experiences', 3, 'sentence', 'She has just arrived.', 'Ela acabou de chegar.', '/ʃiː hæz dʒʌst əˈraɪvd/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"just","pos":"adverb","ipa":"/dʒʌst/","gloss":"só, apenas"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-04', 'lesson-pedagogy-a2-recent-experiences', 4, 'sentence', 'We''ve already eaten.', 'Nós já comemos.', '/wiːv ɔːlˈrɛdi ˈiːtən/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"We''ve","pos":"pronoun","ipa":"/wiːv/","gloss":"nós temos (we have)"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"eaten","pos":"verb","ipa":"/ˈiːtən/","gloss":"comido"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-05', 'lesson-pedagogy-a2-recent-experiences', 5, 'sentence', 'I haven''t finished yet.', 'Eu ainda não terminei.', '/aɪ ˈhævənt ˈfɪnɪʃt jɛt/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-06', 'lesson-pedagogy-a2-recent-experiences', 6, 'sentence', 'Has he called yet?', 'Ele já ligou?', '/hæz hiː kɔːld jɛt/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"Has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"called","pos":"verb","ipa":"/kɔːld/","gloss":"ligou, chamou"},{"surface":"yet","pos":"adverb","ipa":"/jɛt/","gloss":"ainda"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-07', 'lesson-pedagogy-a2-recent-experiences', 7, 'sentence', 'I''ve lost my keys.', 'Eu perdi minhas chaves.', '/aɪv lɔːst maɪ kiːz/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-a2-recent-experiences-08', 'lesson-pedagogy-a2-recent-experiences', 8, 'sentence', 'They haven''t seen this film.', 'Eles não viram este filme.', '/ðeɪ ˈhævənt siːn ðɪs fɪlm/', 'Introdução ao “have/has” + particípio. “Ever/never” trata de experiências; “just/already/yet”, de acontecimentos recentes. O contraste completo com passado vem no B1.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-duration-01', 'lesson-pedagogy-b1-duration', 1, 'sentence', 'I''ve lived here for three years.', 'Moro aqui há três anos.', '/aɪv lɪvd hɪr fɔːr θriː jɪrz/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"three","pos":"numeral","ipa":"/θriː/","gloss":"três"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-02', 'lesson-pedagogy-b1-duration', 2, 'sentence', 'She has worked here since April.', 'Ela trabalha aqui desde abril.', '/ʃiː hæz wɜːrkt hɪr sɪns ˈeɪprəl/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"worked","pos":"verb","ipa":"/wɜːrkt/","gloss":"trabalhou"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"April","pos":"proper noun","ipa":"/ˈeɪprəl/","gloss":"abril"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-03', 'lesson-pedagogy-b1-duration', 3, 'sentence', 'How long have you known him?', 'Há quanto tempo você o conhece?', '/haʊ lɔːŋ hæv juː noʊn hɪm/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"known","pos":"verb","ipa":"/noʊn/","gloss":"sabido, conhecido"},{"surface":"him","pos":"pronoun","ipa":"/hɪm/","gloss":"ele, o, lhe"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-04', 'lesson-pedagogy-b1-duration', 4, 'sentence', 'We''ve been waiting for an hour.', 'Estamos esperando há uma hora.', '/wiːv bɪn ˈweɪtɪŋ fɔːr ən ˈaʊər/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"We''ve","pos":"pronoun","ipa":"/wiːv/","gloss":"nós temos (we have)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-05', 'lesson-pedagogy-b1-duration', 5, 'sentence', 'I haven''t seen her since Monday.', 'Não a vejo desde segunda-feira.', '/aɪ ˈhævənt siːn hɜːr sɪns ˈmʌndeɪ/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"Monday","pos":"proper noun","ipa":"/ˈmʌndeɪ/","gloss":"segunda-feira"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-06', 'lesson-pedagogy-b1-duration', 6, 'sentence', 'He has been studying all morning.', 'Ele está estudando a manhã inteira.', '/hiː hæz bɪn ˈstʌdiɪŋ ɔːl ˈmɔːrnɪŋ/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"studying","pos":"verb","ipa":"/ˈstʌdiɪŋ/","gloss":"estudando"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-07', 'lesson-pedagogy-b1-duration', 7, 'sentence', 'Have you been here long?', 'Você está aqui há muito tempo?', '/hæv juː bɪn hɪr lɔːŋ/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-duration-08', 'lesson-pedagogy-b1-duration', 8, 'sentence', 'They''ve been friends since school.', 'Eles são amigos desde a época da escola.', '/ðeɪv bɪn frɛndz sɪns skuːl/', '“For” indica duração; “since”, o início de um período. Combine com perfect quando a situação se estende até agora; não use “since three years”.', '[]'::jsonb, '[{"surface":"They''ve","pos":"verb","ipa":"/ðeɪv/","gloss":"eles têm (they have)"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"friends","pos":"noun","ipa":"/frɛndz/","gloss":"amigos"},{"surface":"since","pos":"preposition","ipa":"/sɪns/","gloss":"desde"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-used-to-01', 'lesson-pedagogy-b1-used-to', 1, 'sentence', 'I used to live near the beach.', 'Eu morava perto da praia.', '/aɪ juːzd tuː lɪv nɪr ðə biːtʃ/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"near","pos":"preposition","ipa":"/nɪr/","gloss":"perto de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"beach","pos":"noun","ipa":"/biːtʃ/","gloss":"praia"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-02', 'lesson-pedagogy-b1-used-to', 2, 'sentence', 'She used to work at night.', 'Ela costumava trabalhar à noite.', '/ʃiː juːzd tuː wɜːrk æt naɪt/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-03', 'lesson-pedagogy-b1-used-to', 3, 'sentence', 'We used to walk to school.', 'Nós costumávamos ir a pé para a escola.', '/wiː juːzd tuː wɔːk tuː skuːl/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-04', 'lesson-pedagogy-b1-used-to', 4, 'sentence', 'I didn''t use to drink coffee.', 'Eu não costumava tomar café.', '/aɪ ˈdɪdənt juːz tuː drɪŋk ˈkɔːfi/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"drink","pos":"verb","ipa":"/drɪŋk/","gloss":"beber"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-05', 'lesson-pedagogy-b1-used-to', 5, 'sentence', 'Did you use to play football?', 'Você costumava jogar futebol?', '/dɪd juː juːz tuː pleɪ ˈfʊtbɔːl/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"},{"surface":"football","pos":"noun","ipa":"/ˈfʊtbɔːl/","gloss":"futebol"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-06', 'lesson-pedagogy-b1-used-to', 6, 'sentence', 'This building used to be a school.', 'Este prédio era uma escola.', '/ðɪs ˈbɪldɪŋ juːzd tuː biː ə skuːl/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"building","pos":"noun","ipa":"/ˈbɪldɪŋ/","gloss":"prédio"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"school","pos":"noun","ipa":"/skuːl/","gloss":"escola"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-07', 'lesson-pedagogy-b1-used-to', 7, 'sentence', 'He used to be very quiet.', 'Ele era muito quieto.', '/hiː juːzd tuː biː ˈvɛri ˈkwaɪət/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"quiet","pos":"adjective","ipa":"/ˈkwaɪət/","gloss":"quieto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-used-to-08', 'lesson-pedagogy-b1-used-to', 8, 'sentence', 'I used to drive to work, but now I take the bus.', 'Eu ia de carro para o trabalho, mas agora pego o ônibus.', '/aɪ juːzd tuː draɪv tuː wɜːrk bʌt naʊ aɪ teɪk ðə bʌs/', '“Used to” + verbo base descreve hábito ou estado que mudou. Em perguntas/negativas com “did”, use “use to”. Não confunda com “be used to”.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-simple-relatives-01', 'lesson-pedagogy-b1-simple-relatives', 1, 'sentence', 'She''s the teacher who helped me.', 'Ela é a professora que me ajudou.', '/ʃiːz ðə ˈtiːtʃər huː hɛlpt miː/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"She''s","pos":"pronoun","ipa":"/ʃiːz/","gloss":"ela é, ela está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"teacher","pos":"noun","ipa":"/ˈtiːtʃər/","gloss":"professor, professora"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-02', 'lesson-pedagogy-b1-simple-relatives', 2, 'sentence', 'This is the book that I told you about.', 'Este é o livro de que te falei.', '/ðɪs ɪz ðə bʊk ðæt aɪ toʊld juː əˈbaʊt/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"told","pos":"verb","ipa":"/toʊld/","gloss":"contou, disse"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-03', 'lesson-pedagogy-b1-simple-relatives', 3, 'sentence', 'I need a phone that takes good photos.', 'Preciso de um telefone que tire boas fotos.', '/aɪ niːd ə foʊn ðæt teɪks ɡʊd ˈfoʊtoʊz/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"photos","pos":"noun","ipa":"/ˈfoʊtoʊz/","gloss":"fotos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-04', 'lesson-pedagogy-b1-simple-relatives', 4, 'sentence', 'That''s the cafe where we met.', 'Aquele é o café onde nos conhecemos.', '/ðæts ðə kæˈfeɪ wɛr wiː mɛt/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"That''s","pos":"pronoun","ipa":"/ðæts/","gloss":"isso é"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cafe","pos":"noun","ipa":"/kæˈfeɪ/","gloss":"café, cafeteria"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"met","pos":"verb","ipa":"/mɛt/","gloss":"conheceu, encontrou"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-05', 'lesson-pedagogy-b1-simple-relatives', 5, 'sentence', 'People who work here are friendly.', 'As pessoas que trabalham aqui são simpáticas.', '/ˈpiːpəl huː wɜːrk hɪr ɑːr ˈfrɛndli/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"People","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"friendly","pos":"adjective","ipa":"/ˈfrɛndli/","gloss":"simpático"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-06', 'lesson-pedagogy-b1-simple-relatives', 6, 'sentence', 'The bus that goes downtown stops here.', 'O ônibus que vai ao centro para aqui.', '/ðə bʌs ðæt ɡoʊz ˌdaʊnˈtaʊn stɑːps hɪr/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"goes","pos":"verb","ipa":"/ɡoʊz/","gloss":"vai"},{"surface":"downtown","pos":"adverb","ipa":"/ˌdaʊnˈtaʊn/","gloss":"para o centro"},{"surface":"stops","pos":"noun","ipa":"/stɑːps/","gloss":"paradas"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-07', 'lesson-pedagogy-b1-simple-relatives', 7, 'sentence', 'Is this the place where you work?', 'É aqui que você trabalha?', '/ɪz ðɪs ðə pleɪs wɛr juː wɜːrk/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"place","pos":"noun","ipa":"/pleɪs/","gloss":"lugar"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-simple-relatives-08', 'lesson-pedagogy-b1-simple-relatives', 8, 'sentence', 'I found the keys that you lost.', 'Encontrei as chaves que você perdeu.', '/aɪ faʊnd ðə kiːz ðæt juː lɔːst/', 'Relativas definidoras identificam de quem ou do que se fala: “who” para pessoas; “which/that” para coisas; “where” para lugares nestes exemplos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"keys","pos":"noun","ipa":"/kiːz/","gloss":"chaves"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-polite-questions-01', 'lesson-pedagogy-b1-polite-questions', 1, 'sentence', 'It''s cold today, isn''t it?', 'Está frio hoje, não está?', '/ɪts koʊld təˈdeɪ ˈɪzənt ɪt/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"},{"surface":"isn''t","pos":"auxiliary verb","ipa":"/ˈɪzənt/","gloss":"não é, não está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-02', 'lesson-pedagogy-b1-polite-questions', 2, 'sentence', 'You don''t live here, do you?', 'Você não mora aqui, mora?', '/juː doʊnt lɪv hɪr duː juː/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"live","pos":"verb","ipa":"/lɪv/","gloss":"morar, viver"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-03', 'lesson-pedagogy-b1-polite-questions', 3, 'sentence', 'She can help us, can''t she?', 'Ela pode nos ajudar, não pode?', '/ʃiː kæn hɛlp ʌs kænt ʃiː/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-04', 'lesson-pedagogy-b1-polite-questions', 4, 'sentence', 'They arrived yesterday, didn''t they?', 'Eles chegaram ontem, não foi?', '/ðeɪ əˈraɪvd ˈjɛstərdeɪ ˈdɪdənt ðeɪ/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"yesterday","pos":"adverb","ipa":"/ˈjɛstərdeɪ/","gloss":"ontem"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-05', 'lesson-pedagogy-b1-polite-questions', 5, 'sentence', 'Could you tell me where the station is?', 'Você poderia me dizer onde fica a estação?', '/kʊd juː tɛl miː wɛr ðə ˈsteɪʃən ɪz/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"station","pos":"noun","ipa":"/ˈsteɪʃən/","gloss":"estação"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-06', 'lesson-pedagogy-b1-polite-questions', 6, 'sentence', 'Do you know what time the store opens?', 'Você sabe a que horas a loja abre?', '/duː juː noʊ wʌt taɪm ðə stɔːr ˈoʊpənz/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"opens","pos":"verb","ipa":"/ˈoʊpənz/","gloss":"abre"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-07', 'lesson-pedagogy-b1-polite-questions', 7, 'sentence', 'I''d like to know how much this costs.', 'Gostaria de saber quanto isto custa.', '/aɪd laɪk tuː noʊ haʊ mʌtʃ ðɪs kɔːsts/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"how","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-polite-questions-08', 'lesson-pedagogy-b1-polite-questions', 8, 'sentence', 'Can you tell me if this seat is free?', 'Você pode me dizer se este lugar está livre?', '/kæn juː tɛl miː ɪf ðɪs siːt ɪz friː/', 'Em perguntas indiretas, a oração interna tem ordem afirmativa. Question tags costumam inverter a polaridade: “isn''t it?”, “do you?”.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tell","pos":"verb","ipa":"/tɛl/","gloss":"contar, dizer"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"if","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-reasons-contrast-01', 'lesson-pedagogy-b1-reasons-contrast', 1, 'sentence', 'Although it was raining, we went out.', 'Embora estivesse chovendo, nós saímos.', '/ɔːlˈðoʊ ɪt wɑːz ˈreɪnɪŋ wiː wɛnt aʊt/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"raining","pos":"verb","ipa":"/ˈreɪnɪŋ/","gloss":"chovendo"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-02', 'lesson-pedagogy-b1-reasons-contrast', 2, 'sentence', 'The room was small. However, it was comfortable.', 'O quarto era pequeno. Porém, era confortável.', '/ðə ruːm wɑːz smɔːl haʊˈɛvər ɪt wɑːz ˈkʌmftərbəl/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"comfortable","pos":"adjective","ipa":"/ˈkʌmftərbəl/","gloss":"confortável"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-03', 'lesson-pedagogy-b1-reasons-contrast', 3, 'sentence', 'I missed the bus, so I walked.', 'Perdi o ônibus, então fui a pé.', '/aɪ mɪst ðə bʌs soʊ aɪ wɔːkt/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"walked","pos":"verb","ipa":"/wɔːkt/","gloss":"caminhou"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-04', 'lesson-pedagogy-b1-reasons-contrast', 4, 'sentence', 'The store was closed. Therefore, we came back later.', 'A loja estava fechada. Portanto, voltamos mais tarde.', '/ðə stɔːr wɑːz kloʊzd ˈðɛrfɔːr wiː keɪm bæk ˈleɪtər/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"store","pos":"noun","ipa":"/stɔːr/","gloss":"loja, mercado"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"closed","pos":"verb","ipa":"/kloʊzd/","gloss":"fechou, fechado"},{"surface":"Therefore","pos":"adverb","ipa":"/ˈðɛrfɔːr/","gloss":"portanto"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"came","pos":"verb","ipa":"/keɪm/","gloss":"veio"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-05', 'lesson-pedagogy-b1-reasons-contrast', 5, 'sentence', 'She stayed home because she was tired.', 'Ela ficou em casa porque estava cansada.', '/ʃiː steɪd hoʊm bɪˈkɔːz ʃiː wɑːz ˈtaɪərd/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"stayed","pos":"verb","ipa":"/steɪd/","gloss":"ficou"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-06', 'lesson-pedagogy-b1-reasons-contrast', 6, 'sentence', 'Although I liked the job, I wanted a change.', 'Embora gostasse do emprego, eu queria uma mudança.', '/ɔːlˈðoʊ aɪ laɪkt ðə dʒɑːb aɪ ˈwɑːntɪd ə tʃeɪndʒ/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"liked","pos":"verb","ipa":"/laɪkt/","gloss":"gostou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"wanted","pos":"verb","ipa":"/ˈwɑːntɪd/","gloss":"quis, queria"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-07', 'lesson-pedagogy-b1-reasons-contrast', 7, 'sentence', 'The tickets were expensive, but we bought them.', 'Os ingressos eram caros, mas nós os compramos.', '/ðə ˈtɪkɪts wɜːr ɪkˈspɛnsɪv bʌt wiː bɔːt ðɛm/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tickets","pos":"noun","ipa":"/ˈtɪkɪts/","gloss":"ingressos"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"bought","pos":"verb","ipa":"/bɔːt/","gloss":"comprou"},{"surface":"them","pos":"pronoun","ipa":"/ðɛm/","gloss":"eles, os"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-reasons-contrast-08', 'lesson-pedagogy-b1-reasons-contrast', 8, 'sentence', 'First we had lunch, and then we visited the museum.', 'Primeiro almoçamos, e depois visitamos o museu.', '/fɜːrst wiː hæd lʌntʃ ænd ðɛn wiː ˈvɪzɪtɪd ðə mjuˈziːəm/', '“Although” introduz uma oração; “however” conecta ideias com pontuação própria. “So” e “therefore” indicam consequência, com graus diferentes de formalidade.', '[]'::jsonb, '[{"surface":"First","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"then","pos":"adverb","ipa":"/ðɛn/","gloss":"então, depois"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"visited","pos":"verb","ipa":"/ˈvɪzɪtɪd/","gloss":"visitou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"museum","pos":"noun","ipa":"/mjuˈziːəm/","gloss":"museu"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-probability-01', 'lesson-pedagogy-b1-probability', 1, 'sentence', 'It might rain later.', 'Talvez chova mais tarde.', '/ɪt maɪt reɪn ˈleɪtər/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-02', 'lesson-pedagogy-b1-probability', 2, 'sentence', 'She may be at home.', 'Ela pode estar em casa.', '/ʃiː meɪ biː æt hoʊm/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-03', 'lesson-pedagogy-b1-probability', 3, 'sentence', 'He must be tired after that trip.', 'Ele deve estar cansado depois daquela viagem.', '/hiː mʌst biː ˈtaɪərd ˈæftər ðæt trɪp/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"must","pos":"verb","ipa":"/mʌst/","gloss":"dever, ter que"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-04', 'lesson-pedagogy-b1-probability', 4, 'sentence', 'That can''t be the right address.', 'Esse não pode ser o endereço certo.', '/ðæt kænt biː ðə raɪt ˈædrɛs/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-05', 'lesson-pedagogy-b1-probability', 5, 'sentence', 'They''ll probably arrive soon.', 'Eles provavelmente chegarão logo.', '/ðeɪl ˈprɑːbəbli əˈraɪv suːn/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"They''ll","pos":"pronoun","ipa":"/ðeɪl/","gloss":"eles vão (they will)"},{"surface":"probably","pos":"adverb","ipa":"/ˈprɑːbəbli/","gloss":"provavelmente"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-06', 'lesson-pedagogy-b1-probability', 6, 'sentence', 'I might not go tonight.', 'Talvez eu não vá hoje à noite.', '/aɪ maɪt nɑːt ɡoʊ təˈnaɪt/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"might","pos":"modal verb","ipa":"/maɪt/","gloss":"talvez, poderia"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-07', 'lesson-pedagogy-b1-probability', 7, 'sentence', 'She could be waiting outside.', 'Ela pode estar esperando lá fora.', '/ʃiː kʊd biː ˈweɪtɪŋ ˌaʊtˈsaɪd/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"waiting","pos":"verb","ipa":"/ˈweɪtɪŋ/","gloss":"esperando"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-probability-08', 'lesson-pedagogy-b1-probability', 8, 'sentence', 'I''m not sure, but it may work.', 'Não tenho certeza, mas pode funcionar.', '/aɪm nɑːt ʃʊr bʌt ɪt meɪ wɜːrk/', '“May/might” indica possibilidade. “Must” pode indicar dedução forte; “can''t”, uma conclusão de impossibilidade. Aqui não é obrigação nem habilidade.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-phrasal-context-01', 'lesson-pedagogy-b1-phrasal-context', 1, 'sentence', 'Please turn off the light.', 'Por favor, apague a luz.', '/pliːz tɜːrn ɔːf ðə laɪt/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"light","pos":"adjective","ipa":"/laɪt/","gloss":"claro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-02', 'lesson-pedagogy-b1-phrasal-context', 2, 'sentence', 'It''s too bright. Turn it off.', 'Está claro demais. Apague a luz.', '/ɪts tuː braɪt tɜːrn ɪt ɔːf/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"bright","pos":"adjective","ipa":"/braɪt/","gloss":"vivo, brilhante"},{"surface":"Turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-03', 'lesson-pedagogy-b1-phrasal-context', 3, 'sentence', 'Can you pick me up at six?', 'Você pode me buscar às seis?', '/kæn juː pɪk miː ʌp æt sɪks/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"six","pos":"numeral","ipa":"/sɪks/","gloss":"seis"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-04', 'lesson-pedagogy-b1-phrasal-context', 4, 'sentence', 'I''ll look after the children.', 'Vou cuidar das crianças.', '/aɪl lʊk ˈæftər ðə ˈtʃɪldrən/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-05', 'lesson-pedagogy-b1-phrasal-context', 5, 'sentence', 'We ran out of milk.', 'Nosso leite acabou.', '/wiː ræn aʊt ʌv mɪlk/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-06', 'lesson-pedagogy-b1-phrasal-context', 6, 'sentence', 'Please fill in this form.', 'Por favor, preencha este formulário.', '/pliːz fɪl ɪn ðɪs fɔːrm/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"form","pos":"noun","ipa":"/fɔːrm/","gloss":"formulário"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-07', 'lesson-pedagogy-b1-phrasal-context', 7, 'sentence', 'I need to find out what happened.', 'Preciso descobrir o que aconteceu.', '/aɪ niːd tuː faɪnd aʊt wʌt ˈhæpənd/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"find","pos":"verb","ipa":"/faɪnd/","gloss":"encontrar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"happened","pos":"verb","ipa":"/ˈhæpənd/","gloss":"aconteceu"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-phrasal-context-08', 'lesson-pedagogy-b1-phrasal-context', 8, 'sentence', 'Don''t give up now.', 'Não desista agora.', '/doʊnt ɡɪv ʌp naʊ/', 'Aprenda o sentido da combinação. Em phrasal verbs separáveis, um pronome de objeto vai no meio: “turn it off”. Outros, como “look after”, não se separam.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b1-integrated-01', 'lesson-pedagogy-b1-integrated', 1, 'sentence', 'I missed the train because I left home late.', 'Perdi o trem porque saí de casa tarde.', '/aɪ mɪst ðə treɪn bɪˈkɔːz aɪ lɛft hoʊm leɪt/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"because","pos":"conjunction","ipa":"/bɪˈkɔːz/","gloss":"porque"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-02', 'lesson-pedagogy-b1-integrated', 2, 'sentence', 'What happened after that?', 'O que aconteceu depois disso?', '/wʌt ˈhæpənd ˈæftər ðæt/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"happened","pos":"verb","ipa":"/ˈhæpənd/","gloss":"aconteceu"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-03', 'lesson-pedagogy-b1-integrated', 3, 'sentence', 'Luckily, there was another train an hour later.', 'Por sorte, havia outro trem uma hora depois.', '/ˈlʌkɪli ðɛr wɑːz əˈnʌðər treɪn ən ˈaʊər ˈleɪtər/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"Luckily","pos":"adverb","ipa":"/ˈlʌkɪli/","gloss":"por sorte"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-04', 'lesson-pedagogy-b1-integrated', 4, 'sentence', 'How long did you have to wait?', 'Quanto tempo você teve que esperar?', '/haʊ lɔːŋ dɪd juː hæv tuː weɪt/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-05', 'lesson-pedagogy-b1-integrated', 5, 'sentence', 'I''ve had the same problem before.', 'Já tive o mesmo problema antes.', '/aɪv hæd ðə seɪm ˈprɑːbləm bɪˈfɔːr/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"I''ve","pos":"pronoun","ipa":"/aɪv/","gloss":"eu tenho (I have)"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-06', 'lesson-pedagogy-b1-integrated', 6, 'sentence', 'If I were you, I''d leave earlier next time.', 'Se eu fosse você, sairia mais cedo da próxima vez.', '/ɪf aɪ wɜːr juː aɪd liːv ˈɜːrliər nɛkst taɪm/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"earlier","pos":"adverb","ipa":"/ˈɜːrliər/","gloss":"mais cedo, antes"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-07', 'lesson-pedagogy-b1-integrated', 7, 'sentence', 'Do you mean the train was late too?', 'Você quer dizer que o trem também estava atrasado?', '/duː juː miːn ðə treɪn wɑːz leɪt tuː/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"late","pos":"adjective","ipa":"/leɪt/","gloss":"atrasado"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b1-integrated-08', 'lesson-pedagogy-b1-integrated', 8, 'sentence', 'Yes, but we finally arrived on time.', 'Sim, mas finalmente chegamos a tempo.', '/jɛs bʌt wiː ˈfaɪnəli əˈraɪvd ɑːn taɪm/', 'Integre os padrões já estudados: narrativa no passado, razão, pergunta de continuidade e esclarecimento. Os exemplos são falas independentes de situações cotidianas.', '[]'::jsonb, '[{"surface":"Yes","pos":"interjection","ipa":"/jɛs/","gloss":"sim"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"finally","pos":"adverb","ipa":"/ˈfaɪnəli/","gloss":"finalmente"},{"surface":"arrived","pos":"verb","ipa":"/əˈraɪvd/","gloss":"chegou"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-future-perfect-01', 'lesson-pedagogy-b2-future-perfect', 1, 'sentence', 'This time tomorrow, I''ll be flying to Rome.', 'A esta hora amanhã, estarei voando para Roma.', '/ðɪs taɪm təˈmɑːroʊ aɪl biː ˈflaɪɪŋ tuː roʊm/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"flying","pos":"verb","ipa":"/ˈflaɪɪŋ/","gloss":"voando"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Rome","pos":"proper noun","ipa":"/roʊm/","gloss":"Roma"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-02', 'lesson-pedagogy-b2-future-perfect', 2, 'sentence', 'Don''t call at eight. We''ll be having dinner.', 'Não ligue às oito. Estaremos jantando.', '/doʊnt kɔːl æt eɪt wiːl biː ˈhævɪŋ ˈdɪnər/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"Don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"eight","pos":"numeral","ipa":"/eɪt/","gloss":"oito"},{"surface":"We''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-03', 'lesson-pedagogy-b2-future-perfect', 3, 'sentence', 'Will you be using the car tonight?', 'Você vai estar usando o carro hoje à noite?', '/wɪl juː biː ˈjuːzɪŋ ðə kɑːr təˈnaɪt/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"Will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"using","pos":"verb","ipa":"/ˈjuːzɪŋ/","gloss":"usando"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"tonight","pos":"adverb","ipa":"/təˈnaɪt/","gloss":"hoje à noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-04', 'lesson-pedagogy-b2-future-perfect', 4, 'sentence', 'By Friday, I''ll have finished the report.', 'Até sexta-feira, terei terminado o relatório.', '/baɪ ˈfraɪdeɪ aɪl hæv ˈfɪnɪʃt ðə rɪˈpɔːrt/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"},{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-05', 'lesson-pedagogy-b2-future-perfect', 5, 'sentence', 'She''ll have left by the time we arrive.', 'Ela já terá saído quando chegarmos.', '/ʃiːl hæv lɛft baɪ ðə taɪm wiː əˈraɪv/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"She''ll","pos":"verb","ipa":"/ʃiːl/","gloss":"ela vai (she will)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"by","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-06', 'lesson-pedagogy-b2-future-perfect', 6, 'sentence', 'We won''t have finished before noon.', 'Não teremos terminado antes do meio-dia.', '/wiː woʊnt hæv ˈfɪnɪʃt bɪˈfɔːr nuːn/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"noon","pos":"noun","ipa":"/nuːn/","gloss":"meio-dia"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-07', 'lesson-pedagogy-b2-future-perfect', 7, 'sentence', 'What will you be doing this time next week?', 'O que você estará fazendo a esta hora na semana que vem?', '/wʌt wɪl juː biː ˈduːɪŋ ðɪs taɪm nɛkst wiːk/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"doing","pos":"verb","ipa":"/ˈduːɪŋ/","gloss":"fazendo, fazer"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-future-perfect-08', 'lesson-pedagogy-b2-future-perfect', 8, 'sentence', 'By next month, we''ll have lived here for a year.', 'No mês que vem, teremos completado um ano morando aqui.', '/baɪ nɛkst mʌnθ wiːl hæv lɪvd hɪr fɔːr ə jɪr/', '“Will be” + “-ing” indica ação em andamento no futuro; “will have” + particípio indica conclusão antes de um ponto futuro. “By” marca o prazo de referência.', '[]'::jsonb, '[{"surface":"By","pos":"preposition","ipa":"/baɪ/","gloss":"até (prazo)"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"lived","pos":"verb","ipa":"/lɪvd/","gloss":"morou, viveu"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-accustomed-01', 'lesson-pedagogy-b2-accustomed', 1, 'sentence', 'I''m used to getting up early.', 'Estou acostumado a acordar cedo.', '/aɪm juːzd tuː ˈɡɛtɪŋ ʌp ˈɜːrli/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"getting","pos":"verb","ipa":"/ˈɡɛtɪŋ/","gloss":"ficando; getting up = levantar-se"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-02', 'lesson-pedagogy-b2-accustomed', 2, 'sentence', 'She''s used to the noise.', 'Ela está acostumada com o barulho.', '/ʃiːz juːzd tuː ðə nɔɪz/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"She''s","pos":"pronoun","ipa":"/ʃiːz/","gloss":"ela é, ela está"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-03', 'lesson-pedagogy-b2-accustomed', 3, 'sentence', 'We''re getting used to living here.', 'Estamos nos acostumando a morar aqui.', '/wɪr ˈɡɛtɪŋ juːzd tuː ˈlɪvɪŋ hɪr/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"getting","pos":"verb","ipa":"/ˈɡɛtɪŋ/","gloss":"ficando; getting up = levantar-se"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-04', 'lesson-pedagogy-b2-accustomed', 4, 'sentence', 'It took me a while to get used to driving on the left.', 'Levei um tempo para me acostumar a dirigir pela esquerda.', '/ɪt tʊk miː ə waɪl tuː ɡɛt juːzd tuː ˈdraɪvɪŋ ɑːn ðə lɛft/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"driving","pos":"verb","ipa":"/ˈdraɪvɪŋ/","gloss":"dirigindo"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-05', 'lesson-pedagogy-b2-accustomed', 5, 'sentence', 'I''m not used to speaking in public.', 'Não estou acostumado a falar em público.', '/aɪm nɑːt juːzd tuː ˈspiːkɪŋ ɪn ˈpʌblɪk/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"speaking","pos":"verb","ipa":"/ˈspiːkɪŋ/","gloss":"falar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"public","pos":"adjective","ipa":"/ˈpʌblɪk/","gloss":"público"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-06', 'lesson-pedagogy-b2-accustomed', 6, 'sentence', 'Are you used to working at night?', 'Você está acostumado a trabalhar à noite?', '/ɑːr juː juːzd tuː ˈwɜːrkɪŋ æt naɪt/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-07', 'lesson-pedagogy-b2-accustomed', 7, 'sentence', 'I used to work at night, but now I work during the day.', 'Eu costumava trabalhar à noite, mas agora trabalho de dia.', '/aɪ juːzd tuː wɜːrk æt naɪt bʌt naʊ aɪ wɜːrk ˈdʊrɪŋ ðə deɪ/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-accustomed-08', 'lesson-pedagogy-b2-accustomed', 8, 'sentence', 'You''ll get used to it eventually.', 'Você vai se acostumar com isso com o tempo.', '/juːl ɡɛt juːzd tuː ɪt ɪˈvɛntʃuəli/', '“Be used to” indica familiaridade; “get used to”, adaptação. Nesse uso, “to” é preposição e pode vir antes de “-ing”; “used to” + base é um hábito passado.', '[]'::jsonb, '[{"surface":"You''ll","pos":"pronoun","ipa":"/juːl/","gloss":"você vai (you will)"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"used","pos":"verb","ipa":"/juːzd/","gloss":"usou, usado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"eventually","pos":"adverb","ipa":"/ɪˈvɛntʃuəli/","gloss":"com o tempo, finalmente"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-intensity-01', 'lesson-pedagogy-b2-intensity', 1, 'sentence', 'The room is a little cold.', 'O quarto está um pouco frio.', '/ðə ruːm ɪz ə ˈlɪtəl koʊld/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"room","pos":"noun","ipa":"/ruːm/","gloss":"quarto"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"little","pos":"adjective","ipa":"/ˈlɪtəl/","gloss":"pouco, pequeno"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-02', 'lesson-pedagogy-b2-intensity', 2, 'sentence', 'It''s absolutely freezing outside.', 'Está congelante lá fora.', '/ɪts ˌæbsəˈluːtli ˈfriːzɪŋ ˌaʊtˈsaɪd/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"absolutely","pos":"adverb","ipa":"/ˌæbsəˈluːtli/","gloss":"absolutamente"},{"surface":"freezing","pos":"adjective","ipa":"/ˈfriːzɪŋ/","gloss":"congelante"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-03', 'lesson-pedagogy-b2-intensity', 3, 'sentence', 'I was very tired after work.', 'Eu estava muito cansado depois do trabalho.', '/aɪ wɑːz ˈvɛri ˈtaɪərd ˈæftər wɜːrk/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-04', 'lesson-pedagogy-b2-intensity', 4, 'sentence', 'She was absolutely exhausted.', 'Ela estava completamente exausta.', '/ʃiː wɑːz ˌæbsəˈluːtli ɪɡˈzɔːstɪd/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"absolutely","pos":"adverb","ipa":"/ˌæbsəˈluːtli/","gloss":"absolutamente"},{"surface":"exhausted","pos":"adjective","ipa":"/ɪɡˈzɔːstɪd/","gloss":"exausto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-05', 'lesson-pedagogy-b2-intensity', 5, 'sentence', 'The film was quite interesting.', 'O filme foi bastante interessante.', '/ðə fɪlm wɑːz kwaɪt ˈɪntrəstɪŋ/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"film","pos":"noun","ipa":"/fɪlm/","gloss":"filme"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"quite","pos":"adverb","ipa":"/kwaɪt/","gloss":"bem, bastante"},{"surface":"interesting","pos":"adjective","ipa":"/ˈɪntrəstɪŋ/","gloss":"interessante"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-06', 'lesson-pedagogy-b2-intensity', 6, 'sentence', 'That was absolutely amazing.', 'Aquilo foi realmente incrível.', '/ðæt wɑːz ˌæbsəˈluːtli əˈmeɪzɪŋ/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"absolutely","pos":"adverb","ipa":"/ˌæbsəˈluːtli/","gloss":"absolutamente"},{"surface":"amazing","pos":"adjective","ipa":"/əˈmeɪzɪŋ/","gloss":"incrível"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-07', 'lesson-pedagogy-b2-intensity', 7, 'sentence', 'I''m completely sure about this.', 'Tenho plena certeza disso.', '/aɪm kəmˈpliːtli ʃʊr əˈbaʊt ðɪs/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"completely","pos":"adverb","ipa":"/kəmˈpliːtli/","gloss":"completamente"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-intensity-08', 'lesson-pedagogy-b2-intensity', 8, 'sentence', 'The answer is fairly simple.', 'A resposta é relativamente simples.', '/ðə ˈænsər ɪz ˈfɛrli ˈsɪmpəl/', 'Adjetivos graduáveis combinam com graus como “very” e “a little”. Adjetivos de sentido extremo combinam frequentemente com “absolutely”; aprenda combinações naturais.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"answer","pos":"noun","ipa":"/ˈænsər/","gloss":"resposta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"fairly","pos":"adverb","ipa":"/ˈfɛrli/","gloss":"bastante, razoavelmente"},{"surface":"simple","pos":"adjective","ipa":"/ˈsɪmpəl/","gloss":"simples"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-reference-articles-01', 'lesson-pedagogy-b2-reference-articles', 1, 'sentence', 'I like music, but I didn''t like the music at the party.', 'Gosto de música, mas não gostei da música da festa.', '/aɪ laɪk ˈmjuːzɪk bʌt aɪ ˈdɪdənt laɪk ðə ˈmjuːzɪk æt ðə ˈpɑːrti/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"music","pos":"noun","ipa":"/ˈmjuːzɪk/","gloss":"música"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-02', 'lesson-pedagogy-b2-reference-articles', 2, 'sentence', 'Children need time to play.', 'As crianças precisam de tempo para brincar.', '/ˈtʃɪldrən niːd taɪm tuː pleɪ/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"Children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-03', 'lesson-pedagogy-b2-reference-articles', 3, 'sentence', 'The children next door are playing outside.', 'As crianças da casa ao lado estão brincando lá fora.', '/ðə ˈtʃɪldrən nɛkst dɔːr ɑːr ˈpleɪɪŋ ˌaʊtˈsaɪd/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"playing","pos":"verb","ipa":"/ˈpleɪɪŋ/","gloss":"jogando, brincando"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-04', 'lesson-pedagogy-b2-reference-articles', 4, 'sentence', 'Life can be difficult sometimes.', 'A vida pode ser difícil às vezes.', '/laɪf kæn biː ˈdɪfɪkəlt ˈsʌmtaɪmz/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"Life","pos":"noun","ipa":"/laɪf/","gloss":"vida"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"difficult","pos":"adjective","ipa":"/ˈdɪfɪkəlt/","gloss":"difícil"},{"surface":"sometimes","pos":"adverb","ipa":"/ˈsʌmtaɪmz/","gloss":"às vezes"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-05', 'lesson-pedagogy-b2-reference-articles', 5, 'sentence', 'The life he described was very different from mine.', 'A vida que ele descreveu era muito diferente da minha.', '/ðə laɪf hiː dɪˈskraɪbd wɑːz ˈvɛri ˈdɪfərənt frʌm maɪn/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"life","pos":"noun","ipa":"/laɪf/","gloss":"vida"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"described","pos":"verb","ipa":"/dɪˈskraɪbd/","gloss":"descreveu"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"different","pos":"adjective","ipa":"/ˈdɪfərənt/","gloss":"diferente"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"mine","pos":"pronoun","ipa":"/maɪn/","gloss":"meu, minha (sem substantivo)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-06', 'lesson-pedagogy-b2-reference-articles', 6, 'sentence', 'I usually have breakfast at home.', 'Geralmente tomo café da manhã em casa.', '/aɪ ˈjuːʒuəli hæv ˈbrɛkfəst æt hoʊm/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-07', 'lesson-pedagogy-b2-reference-articles', 7, 'sentence', 'The breakfast at the hotel was excellent.', 'O café da manhã do hotel foi excelente.', '/ðə ˈbrɛkfəst æt ðə hoʊˈtɛl wɑːz ˈɛksələnt/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","gloss":"café da manhã"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"hotel","pos":"noun","ipa":"/hoʊˈtɛl/","gloss":"hotel"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"excellent","pos":"adjective","ipa":"/ˈɛksələnt/","gloss":"excelente"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-reference-articles-08', 'lesson-pedagogy-b2-reference-articles', 8, 'sentence', 'She wants to become an engineer.', 'Ela quer se tornar engenheira.', '/ʃiː wɑːnts tuː bɪˈkʌm ən ˌɛndʒɪˈnɪr/', 'O artigo muda conforme a referência. Plurais/incontáveis gerais frequentemente não usam “the”; algo identificado usa. As notas não significam que todo nome tenha a mesma regra.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"wants","pos":"verb","ipa":"/wɑːnts/","gloss":"quer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"become","pos":"verb","ipa":"/bɪˈkʌm/","gloss":"tornar-se"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"engineer","pos":"noun","ipa":"/ˌɛndʒɪˈnɪr/","gloss":"engenheiro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-unless-01', 'lesson-pedagogy-b2-unless', 1, 'sentence', 'Unless it rains, we''ll have lunch outside.', 'A menos que chova, almoçaremos lá fora.', '/ənˈlɛs ɪt reɪnz wiːl hæv lʌntʃ ˌaʊtˈsaɪd/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"Unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"rains","pos":"verb","ipa":"/reɪnz/","gloss":"chove"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"},{"surface":"outside","pos":"adverb","ipa":"/ˌaʊtˈsaɪd/","gloss":"lá fora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-02', 'lesson-pedagogy-b2-unless', 2, 'sentence', 'I won''t go unless you come with me.', 'Não vou a menos que você venha comigo.', '/aɪ woʊnt ɡoʊ ənˈlɛs juː kʌm wɪð miː/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"come","pos":"verb","ipa":"/kʌm/","gloss":"vir; vindo"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-03', 'lesson-pedagogy-b2-unless', 3, 'sentence', 'You can borrow the car as long as you drive carefully.', 'Você pode pegar o carro emprestado, desde que dirija com cuidado.', '/juː kæn ˈbɑːroʊ ðə kɑːr æz lɔːŋ æz juː draɪv ˈkɛrfəli/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"borrow","pos":"verb","ipa":"/ˈbɑːroʊ/","gloss":"pegar emprestado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"drive","pos":"verb","ipa":"/draɪv/","gloss":"dirigir"},{"surface":"carefully","pos":"adverb","ipa":"/ˈkɛrfəli/","gloss":"com cuidado"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-04', 'lesson-pedagogy-b2-unless', 4, 'sentence', 'We''ll accept the offer provided that the price stays the same.', 'Aceitaremos a oferta, desde que o preço continue o mesmo.', '/wiːl əkˈsɛpt ðə ˈɔːfər prəˈvaɪdɪd ðæt ðə praɪs steɪz ðə seɪm/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"We''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"accept","pos":"verb","ipa":"/əkˈsɛpt/","gloss":"aceitar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"offer","pos":"noun","ipa":"/ˈɔːfər/","gloss":"oferta"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"},{"surface":"stays","pos":"verb","ipa":"/steɪz/","gloss":"permanece"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-05', 'lesson-pedagogy-b2-unless', 5, 'sentence', 'Unless we leave now, we''ll miss the train.', 'Se não sairmos agora, perderemos o trem.', '/ənˈlɛs wiː liːv naʊ wiːl mɪs ðə treɪn/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"Unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"},{"surface":"we''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"miss","pos":"verb","ipa":"/mɪs/","gloss":"errar, perder; sentir falta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-06', 'lesson-pedagogy-b2-unless', 6, 'sentence', 'I''ll help as long as you explain what you need.', 'Vou ajudar, desde que você explique do que precisa.', '/aɪl hɛlp æz lɔːŋ æz juː ɪkˈspleɪn wʌt juː niːd/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-07', 'lesson-pedagogy-b2-unless', 7, 'sentence', 'You can join us provided that you book in advance.', 'Você pode se juntar a nós, desde que reserve com antecedência.', '/juː kæn dʒɔɪn ʌs prəˈvaɪdɪd ðæt juː bʊk ɪn ədˈvæns/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"join","pos":"verb","ipa":"/dʒɔɪn/","gloss":"entrar, participar"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"advance","pos":"noun","ipa":"/ədˈvæns/","gloss":"antecedência"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-unless-08', 'lesson-pedagogy-b2-unless', 8, 'sentence', 'We can change the date unless it''s already confirmed.', 'Podemos mudar a data, a menos que ela já esteja confirmada.', '/wiː kæn tʃeɪndʒ ðə deɪt ənˈlɛs ɪts ɔːlˈrɛdi kənˈfɜːrmd/', '“Unless” equivale normalmente a “if not”. “As long as/provided that” estabelece uma condição. Não acrescente “will” automaticamente à oração de condição futura.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"unless","pos":"conjunction","ipa":"/ənˈlɛs/","gloss":"a menos que"},{"surface":"it''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"already","pos":"adverb","ipa":"/ɔːlˈrɛdi/","gloss":"já"},{"surface":"confirmed","pos":"verb","ipa":"/kənˈfɜːrmd/","gloss":"confirmado"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-b2-argument-structure-01', 'lesson-pedagogy-b2-argument-structure', 1, 'sentence', 'In my view, working from home can be a good option.', 'Na minha opinião, trabalhar de casa pode ser uma boa opção.', '/ɪn maɪ vjuː ˈwɜːrkɪŋ frʌm hoʊm kæn biː ə ɡʊd ˈɑːpʃən/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"view","pos":"noun","ipa":"/vjuː/","gloss":"vista"},{"surface":"working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-02', 'lesson-pedagogy-b2-argument-structure', 2, 'sentence', 'One reason is that it saves travel time.', 'Uma razão é que isso economiza tempo de deslocamento.', '/wʌn ˈriːzən ɪz ðæt ɪt seɪvz ˈtrævəl taɪm/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"One","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"reason","pos":"noun","ipa":"/ˈriːzən/","gloss":"motivo, razão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"saves","pos":"verb","ipa":"/seɪvz/","gloss":"economiza"},{"surface":"travel","pos":"verb","ipa":"/ˈtrævəl/","gloss":"viajar"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-03', 'lesson-pedagogy-b2-argument-structure', 3, 'sentence', 'For example, people can spend more time with their families.', 'Por exemplo, as pessoas podem passar mais tempo com suas famílias.', '/fɔːr ɪɡˈzæmpəl ˈpiːpəl kæn spɛnd mɔːr taɪm wɪð ðɛr ˈfæməliz/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"For","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"example","pos":"noun","ipa":"/ɪɡˈzæmpəl/","gloss":"exemplo"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"spend","pos":"verb","ipa":"/spɛnd/","gloss":"gastar, passar (tempo)"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"families","pos":"noun","ipa":"/ˈfæməliz/","gloss":"famílias"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-04', 'lesson-pedagogy-b2-argument-structure', 4, 'sentence', 'However, it doesn''t suit every job.', 'Porém, isso não serve para todos os empregos.', '/haʊˈɛvər ɪt ˈdʌzənt suːt ˈɛvri dʒɑːb/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"However","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"doesn''t","pos":"verb","ipa":"/ˈdʌzənt/","gloss":"não (does not)"},{"surface":"suit","pos":"verb","ipa":"/suːt/","gloss":"servir para, ser adequado"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-05', 'lesson-pedagogy-b2-argument-structure', 5, 'sentence', 'Although it offers flexibility, it can also feel lonely.', 'Embora ofereça flexibilidade, também pode causar solidão.', '/ɔːlˈðoʊ ɪt ˈɔːfərz ˌflɛksəˈbɪləti ɪt kæn ˈɔːlsoʊ fiːl ˈloʊnli/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"Although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"offers","pos":"verb","ipa":"/ˈɔːfərz/","gloss":"oferece"},{"surface":"flexibility","pos":"noun","ipa":"/ˌflɛksəˈbɪləti/","gloss":"flexibilidade"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"also","pos":"adverb","ipa":"/ˈɔːlsoʊ/","gloss":"também"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"lonely","pos":"adjective","ipa":"/ˈloʊnli/","gloss":"sozinho, solitário"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-06', 'lesson-pedagogy-b2-argument-structure', 6, 'sentence', 'Some people argue that an office makes communication easier.', 'Algumas pessoas defendem que um escritório facilita a comunicação.', '/sʌm ˈpiːpəl ˈɑːrɡjuː ðæt ən ˈɔːfɪs meɪks kəˌmjuːnɪˈkeɪʃən ˈiːziər/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"argue","pos":"verb","ipa":"/ˈɑːrɡjuː/","gloss":"defender, sustentar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"office","pos":"noun","ipa":"/ˈɔːfɪs/","gloss":"escritório, balcão"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"communication","pos":"noun","ipa":"/kəˌmjuːnɪˈkeɪʃən/","gloss":"comunicação"},{"surface":"easier","pos":"adjective","ipa":"/ˈiːziər/","gloss":"mais fácil"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-07', 'lesson-pedagogy-b2-argument-structure', 7, 'sentence', 'That is a fair point, but the quality of communication matters too.', 'Esse é um argumento válido, mas a qualidade da comunicação também importa.', '/ðæt ɪz ə fɛr pɔɪnt bʌt ðə ˈkwɑːləti ʌv kəˌmjuːnɪˈkeɪʃən ˈmætərz tuː/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"fair","pos":"adjective","ipa":"/fɛr/","gloss":"justo"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"quality","pos":"noun","ipa":"/ˈkwɑːləti/","gloss":"qualidade"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"communication","pos":"noun","ipa":"/kəˌmjuːnɪˈkeɪʃən/","gloss":"comunicação"},{"surface":"matters","pos":"verb","ipa":"/ˈmætərz/","gloss":"importa"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-b2-argument-structure-08', 'lesson-pedagogy-b2-argument-structure', 8, 'sentence', 'Overall, the best choice depends on the job and the person.', 'De modo geral, a melhor escolha depende do emprego e da pessoa.', '/ˌoʊvərˈɔːl ðə bɛst tʃɔɪs dɪˈpɛndz ɑːn ðə dʒɑːb ænd ðə ˈpɜːrsən/', 'Observe a função de cada frase: apresentar posição, dar razão/exemplo, reconhecer limite e concluir. São modelos de linguagem, não afirmações obrigatórias do aluno.', '[]'::jsonb, '[{"surface":"Overall","pos":"adverb","ipa":"/ˌoʊvərˈɔːl/","gloss":"no geral"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"choice","pos":"noun","ipa":"/tʃɔɪs/","gloss":"escolha"},{"surface":"depends","pos":"verb","ipa":"/dɪˈpɛndz/","gloss":"depende"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"person","pos":"noun","ipa":"/ˈpɜːrsən/","gloss":"pessoa"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-ellipsis-01', 'lesson-pedagogy-c1-ellipsis', 1, 'sentence', 'She said she would call, and she did.', 'Ela disse que ligaria, e ligou.', '/ʃiː sɛd ʃiː wʊd kɔːl ænd ʃiː dɪd/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-02', 'lesson-pedagogy-c1-ellipsis', 2, 'sentence', 'I haven''t read the report, but my colleague has.', 'Não li o relatório, mas minha colega leu.', '/aɪ ˈhævənt riːd ðə rɪˈpɔːrt bʌt maɪ ˈkɑːliːɡ hæz/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"colleague","pos":"noun","ipa":"/ˈkɑːliːɡ/","gloss":"colega de trabalho"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-03', 'lesson-pedagogy-c1-ellipsis', 3, 'sentence', 'Some people prefer to work alone; others don''t.', 'Algumas pessoas preferem trabalhar sozinhas; outras não.', '/sʌm ˈpiːpəl prɪˈfɜːr tuː wɜːrk əˈloʊn ˈʌðərz doʊnt/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"prefer","pos":"verb","ipa":"/prɪˈfɜːr/","gloss":"preferir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"alone","pos":"adverb","ipa":"/əˈloʊn/","gloss":"sozinho"},{"surface":"others","pos":"pronoun","ipa":"/ˈʌðərz/","gloss":"outros"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-04', 'lesson-pedagogy-c1-ellipsis', 4, 'sentence', 'I enjoyed the talk, and so did everyone else.', 'Gostei da palestra, assim como todas as outras pessoas.', '/aɪ ɪnˈdʒɔɪd ðə tɔːk ænd soʊ dɪd ˈɛvriwʌn ɛls/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"enjoyed","pos":"verb","ipa":"/ɪnˈdʒɔɪd/","gloss":"gostou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"everyone","pos":"pronoun","ipa":"/ˈɛvriwʌn/","gloss":"todo mundo, pessoal"},{"surface":"else","pos":"adverb","ipa":"/ɛls/","gloss":"mais, outro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-05', 'lesson-pedagogy-c1-ellipsis', 5, 'sentence', 'I couldn''t attend the meeting, and neither could my manager.', 'Não pude participar da reunião, nem meu gerente.', '/aɪ ˈkʊdənt əˈtɛnd ðə ˈmiːtɪŋ ænd ˈniːðər kʊd maɪ ˈmænɪdʒər/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"couldn''t","pos":"verb","ipa":"/ˈkʊdənt/","gloss":"não podia (could not)"},{"surface":"attend","pos":"verb","ipa":"/əˈtɛnd/","gloss":"comparecer"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"neither","pos":"adverb","ipa":"/ˈniːðər/","gloss":"também não, nenhum dos dois"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-06', 'lesson-pedagogy-c1-ellipsis', 6, 'sentence', 'If you need to change the date, please do so today.', 'Se precisar mudar a data, por favor, faça isso hoje.', '/ɪf juː niːd tuː tʃeɪndʒ ðə deɪt pliːz duː soʊ təˈdeɪ/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"If","pos":"conjunction","ipa":"/ɪf/","gloss":"se"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-07', 'lesson-pedagogy-c1-ellipsis', 7, 'sentence', 'She could have explained the delay, but chose not to.', 'Ela poderia ter explicado o atraso, mas optou por não explicar.', '/ʃiː kʊd hæv ɪkˈspleɪnd ðə dɪˈleɪ bʌt tʃoʊz nɑːt tuː/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"explained","pos":"verb","ipa":"/ɪkˈspleɪnd/","gloss":"explicou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"delay","pos":"noun","ipa":"/dɪˈleɪ/","gloss":"atraso"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"chose","pos":"verb","ipa":"/tʃoʊz/","gloss":"escolheu"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-ellipsis-08', 'lesson-pedagogy-c1-ellipsis', 8, 'sentence', 'Those who wish to leave early may do so.', 'Quem desejar sair mais cedo pode fazê-lo.', '/ðoʊz huː wɪʃ tuː liːv ˈɜːrli meɪ duː soʊ/', 'Uma informação recuperável pode ser omitida ou substituída. A forma auxiliar mantém tempo/polaridade; “do so” retoma uma ação. A aula revisita formas simples antes de ampliar.', '[]'::jsonb, '[{"surface":"Those","pos":"determiner","ipa":"/ðoʊz/","gloss":"aqueles, essas"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"wish","pos":"verb","ipa":"/wɪʃ/","gloss":"desejar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-participle-clauses-01', 'lesson-pedagogy-c1-participle-clauses', 1, 'sentence', 'Having read the report, I understood the problem.', 'Depois de ler o relatório, entendi o problema.', '/ˈhævɪŋ riːd ðə rɪˈpɔːrt aɪ ˌʌndərˈstʊd ðə ˈprɑːbləm/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"read","pos":"verb","ipa":"/riːd/","gloss":"ler"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"understood","pos":"verb","ipa":"/ˌʌndərˈstʊd/","gloss":"entendeu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-02', 'lesson-pedagogy-c1-participle-clauses', 2, 'sentence', 'Feeling tired, she decided to leave early.', 'Como estava cansada, ela decidiu sair cedo.', '/ˈfiːlɪŋ ˈtaɪərd ʃiː dɪˈsaɪdɪd tuː liːv ˈɜːrli/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Feeling","pos":"verb","ipa":"/ˈfiːlɪŋ/","gloss":"sentindo"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"decided","pos":"verb","ipa":"/dɪˈsaɪdɪd/","gloss":"decidiu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-03', 'lesson-pedagogy-c1-participle-clauses', 3, 'sentence', 'Not knowing what to say, he remained silent.', 'Sem saber o que dizer, ele permaneceu em silêncio.', '/nɑːt ˈnoʊɪŋ wʌt tuː seɪ hiː rɪˈmeɪnd ˈsaɪlənt/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"knowing","pos":"verb","ipa":"/ˈnoʊɪŋ/","gloss":"saber, conhecer"},{"surface":"what","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"he","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"remained","pos":"verb","ipa":"/rɪˈmeɪnd/","gloss":"permaneceu"},{"surface":"silent","pos":"adjective","ipa":"/ˈsaɪlənt/","gloss":"em silêncio"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-04', 'lesson-pedagogy-c1-participle-clauses', 4, 'sentence', 'Having finished the work, we went home.', 'Depois de terminar o trabalho, fomos para casa.', '/ˈhævɪŋ ˈfɪnɪʃt ðə wɜːrk wiː wɛnt hoʊm/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"finished","pos":"verb","ipa":"/ˈfɪnɪʃt/","gloss":"terminou, terminado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-05', 'lesson-pedagogy-c1-participle-clauses', 5, 'sentence', 'Written in simple language, the guide is easy to follow.', 'Escrito em linguagem simples, o guia é fácil de acompanhar.', '/ˈrɪtən ɪn ˈsɪmpəl ˈlæŋɡwɪdʒ ðə ɡaɪd ɪz ˈiːzi tuː ˈfɑːloʊ/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Written","pos":"verb","ipa":"/ˈrɪtən/","gloss":"escrito"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"simple","pos":"adjective","ipa":"/ˈsɪmpəl/","gloss":"simples"},{"surface":"language","pos":"noun","ipa":"/ˈlæŋɡwɪdʒ/","gloss":"língua, idioma"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"guide","pos":"noun","ipa":"/ɡaɪd/","gloss":"guia"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"easy","pos":"adjective","ipa":"/ˈiːzi/","gloss":"fácil, tranquilo"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"follow","pos":"verb","ipa":"/ˈfɑːloʊ/","gloss":"seguir"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-06', 'lesson-pedagogy-c1-participle-clauses', 6, 'sentence', 'Seen from a distance, the building looks smaller.', 'Visto de longe, o prédio parece menor.', '/siːn frʌm ə ˈdɪstəns ðə ˈbɪldɪŋ lʊks ˈsmɔːlər/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Seen","pos":"verb","ipa":"/siːn/","gloss":"visto"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"distance","pos":"noun","ipa":"/ˈdɪstəns/","gloss":"distância"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"building","pos":"noun","ipa":"/ˈbɪldɪŋ/","gloss":"prédio"},{"surface":"looks","pos":"verb","ipa":"/lʊks/","gloss":"parece, fica"},{"surface":"smaller","pos":"adjective","ipa":"/ˈsmɔːlər/","gloss":"menor"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-07', 'lesson-pedagogy-c1-participle-clauses', 7, 'sentence', 'Working together, they found a better solution.', 'Trabalhando juntos, eles encontraram uma solução melhor.', '/ˈwɜːrkɪŋ təˈɡɛðər ðeɪ faʊnd ə ˈbɛtər səˈluːʃən/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Working","pos":"verb","ipa":"/ˈwɜːrkɪŋ/","gloss":"funcionando; trabalhando"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"better","pos":"adjective","ipa":"/ˈbɛtər/","gloss":"melhor"},{"surface":"solution","pos":"noun","ipa":"/səˈluːʃən/","gloss":"solução"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-participle-clauses-08', 'lesson-pedagogy-c1-participle-clauses', 8, 'sentence', 'Having been warned about the risk, she checked everything again.', 'Depois de ter sido alertada sobre o risco, ela conferiu tudo de novo.', '/ˈhævɪŋ bɪn wɔːrnd əˈbaʊt ðə rɪsk ʃiː tʃɛkt ˈɛvriθɪŋ əˈɡɛn/', 'Uma oração com particípio pode condensar informações. Nos exemplos de ação, mantenha claro o sujeito compartilhado; evite ligar a ação reduzida ao sujeito errado.', '[]'::jsonb, '[{"surface":"Having","pos":"verb","ipa":"/ˈhævɪŋ/","gloss":"receber, ter"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"},{"surface":"warned","pos":"verb","ipa":"/wɔːrnd/","gloss":"avisou, alertou"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"risk","pos":"noun","ipa":"/rɪsk/","gloss":"risco"},{"surface":"she","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"checked","pos":"verb","ipa":"/tʃɛkt/","gloss":"verificou, marcou"},{"surface":"everything","pos":"pronoun","ipa":"/ˈɛvriθɪŋ/","gloss":"tudo"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-reporting-passives-01', 'lesson-pedagogy-c1-reporting-passives', 1, 'sentence', 'It is reported that the road will reopen tomorrow.', 'Segundo as informações divulgadas, a estrada será reaberta amanhã.', '/ɪt ɪz rɪˈpɔːrtɪd ðæt ðə roʊd wɪl ˌriːˈoʊpən təˈmɑːroʊ/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"reported","pos":"verb","ipa":"/rɪˈpɔːrtɪd/","gloss":"relatado"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"road","pos":"noun","ipa":"/roʊd/","gloss":"estrada"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"reopen","pos":"verb","ipa":"/ˌriːˈoʊpən/","gloss":"reabrir"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-02', 'lesson-pedagogy-c1-reporting-passives', 2, 'sentence', 'The company is said to be planning a change.', 'Diz-se que a empresa está planejando uma mudança.', '/ðə ˈkʌmpəni ɪz sɛd tuː biː ˈplænɪŋ ə tʃeɪndʒ/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"company","pos":"noun","ipa":"/ˈkʌmpəni/","gloss":"empresa"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"planning","pos":"verb","ipa":"/ˈplænɪŋ/","gloss":"planejando"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-03', 'lesson-pedagogy-c1-reporting-passives', 3, 'sentence', 'The decision is believed to have caused further delays.', 'Acredita-se que a decisão tenha causado mais atrasos.', '/ðə dɪˈsɪʒən ɪz bɪˈliːvd tuː hæv kɔːzd ˈfɜːrðər dɪˈleɪz/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"believed","pos":"verb","ipa":"/bɪˈliːvd/","gloss":"acreditou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"caused","pos":"verb","ipa":"/kɔːzd/","gloss":"causou"},{"surface":"further","pos":"adjective","ipa":"/ˈfɜːrðər/","gloss":"adicional, mais"},{"surface":"delays","pos":"noun","ipa":"/dɪˈleɪz/","gloss":"atrasos"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-04', 'lesson-pedagogy-c1-reporting-passives', 4, 'sentence', 'It is expected that the results will be available next week.', 'Espera-se que os resultados estejam disponíveis na próxima semana.', '/ɪt ɪz ɪkˈspɛktɪd ðæt ðə rɪˈzʌlts wɪl biː əˈveɪləbəl nɛkst wiːk/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"expected","pos":"verb","ipa":"/ɪkˈspɛktɪd/","gloss":"esperado"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"available","pos":"adjective","ipa":"/əˈveɪləbəl/","gloss":"disponível"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-05', 'lesson-pedagogy-c1-reporting-passives', 5, 'sentence', 'The building is thought to be over a hundred years old.', 'Acredita-se que o prédio tenha mais de cem anos.', '/ðə ˈbɪldɪŋ ɪz θɔːt tuː biː ˈoʊvər ə ˈhʌndrəd jɪrz oʊld/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"building","pos":"noun","ipa":"/ˈbɪldɪŋ/","gloss":"prédio"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"thought","pos":"verb","ipa":"/θɔːt/","gloss":"pensou, pensado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"over","pos":"preposition","ipa":"/ˈoʊvər/","gloss":"por cima; superado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"hundred","pos":"numeral","ipa":"/ˈhʌndrəd/","gloss":"cem, centena"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-06', 'lesson-pedagogy-c1-reporting-passives', 6, 'sentence', 'Several people are reported to have left the meeting early.', 'Segundo relatos, várias pessoas saíram da reunião mais cedo.', '/ˈsɛvrəl ˈpiːpəl ɑːr rɪˈpɔːrtɪd tuː hæv lɛft ðə ˈmiːtɪŋ ˈɜːrli/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"Several","pos":"determiner","ipa":"/ˈsɛvrəl/","gloss":"vários"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"reported","pos":"verb","ipa":"/rɪˈpɔːrtɪd/","gloss":"relatado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"early","pos":"adverb","ipa":"/ˈɜːrli/","gloss":"cedo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-07', 'lesson-pedagogy-c1-reporting-passives', 7, 'sentence', 'It is generally accepted that more evidence is needed.', 'É geralmente aceito que são necessárias mais evidências.', '/ɪt ɪz ˈdʒɛnərəli əkˈsɛptɪd ðæt mɔːr ˈɛvɪdəns ɪz ˈniːdɪd/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"generally","pos":"adverb","ipa":"/ˈdʒɛnərəli/","gloss":"geralmente"},{"surface":"accepted","pos":"verb","ipa":"/əkˈsɛptɪd/","gloss":"aceito"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"needed","pos":"verb","ipa":"/ˈniːdɪd/","gloss":"precisou"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-reporting-passives-08', 'lesson-pedagogy-c1-reporting-passives', 8, 'sentence', 'The problem is understood to have started last month.', 'Pelo que se sabe, o problema começou no mês passado.', '/ðə ˈprɑːbləm ɪz ˌʌndərˈstʊd tuː hæv ˈstɑːrtɪd læst mʌnθ/', '“It is reported/believed that” destaca a informação e a atribui a outros. “Is said to” e “is believed to have” mudam a estrutura; cautela e fonte importam.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"understood","pos":"verb","ipa":"/ˌʌndərˈstʊd/","gloss":"entendeu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-cohesion-01', 'lesson-pedagogy-c1-cohesion', 1, 'sentence', 'The first plan was too expensive. This led us to consider another option.', 'O primeiro plano era caro demais. Isso nos levou a considerar outra opção.', '/ðə fɜːrst plæn wɑːz tuː ɪkˈspɛnsɪv ðɪs lɛd ʌs tuː kənˈsɪdər əˈnʌðər ˈɑːpʃən/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"too","pos":"adverb","ipa":"/tuː/","gloss":"demais"},{"surface":"expensive","pos":"adjective","ipa":"/ɪkˈspɛnsɪv/","gloss":"caro"},{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"led","pos":"verb","ipa":"/lɛd/","gloss":"liderou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"consider","pos":"verb","ipa":"/kənˈsɪdər/","gloss":"considerar"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-02', 'lesson-pedagogy-c1-cohesion', 2, 'sentence', 'The team changed its approach. This decision improved the results.', 'A equipe mudou sua abordagem. Essa decisão melhorou os resultados.', '/ðə tiːm tʃeɪndʒd ɪts əˈproʊtʃ ðɪs dɪˈsɪʒən ɪmˈpruːvd ðə rɪˈzʌlts/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"},{"surface":"changed","pos":"verb","ipa":"/tʃeɪndʒd/","gloss":"mudou, mudado"},{"surface":"its","pos":"determiner","ipa":"/ɪts/","gloss":"seu, sua (de coisa)"},{"surface":"approach","pos":"noun","ipa":"/əˈproʊtʃ/","gloss":"abordagem"},{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"},{"surface":"improved","pos":"verb","ipa":"/ɪmˈpruːvd/","gloss":"melhorou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-03', 'lesson-pedagogy-c1-cohesion', 3, 'sentence', 'Some people questioned the cost. These concerns were discussed at the meeting.', 'Algumas pessoas questionaram o custo. Essas preocupações foram discutidas na reunião.', '/sʌm ˈpiːpəl ˈkwɛstʃənd ðə kɔːst ðiːz kənˈsɜːrnz wɜːr dɪˈskʌst æt ðə ˈmiːtɪŋ/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"Some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"people","pos":"noun","ipa":"/ˈpiːpəl/","gloss":"pessoas"},{"surface":"questioned","pos":"verb","ipa":"/ˈkwɛstʃənd/","gloss":"questionou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"},{"surface":"These","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"concerns","pos":"noun","ipa":"/kənˈsɜːrnz/","gloss":"preocupações"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"discussed","pos":"verb","ipa":"/dɪˈskʌst/","gloss":"discutido, conversado"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-04', 'lesson-pedagogy-c1-cohesion', 4, 'sentence', 'The data was incomplete. Nevertheless, it provided a useful starting point.', 'Os dados estavam incompletos. Ainda assim, forneceram um ponto de partida útil.', '/ðə ˈdeɪtə wɑːz ˌɪnkəmˈpliːt ˌnɛvərðəˈlɛs ɪt prəˈvaɪdɪd ə ˈjuːsfəl ˈstɑːrtɪŋ pɔɪnt/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"data","pos":"noun","ipa":"/ˈdeɪtə/","gloss":"dados"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"incomplete","pos":"adjective","ipa":"/ˌɪnkəmˈpliːt/","gloss":"incompleto"},{"surface":"Nevertheless","pos":"adverb","ipa":"/ˌnɛvərðəˈlɛs/","gloss":"no entanto"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"provided","pos":"conjunction","ipa":"/prəˈvaɪdɪd/","gloss":"desde que"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"useful","pos":"adjective","ipa":"/ˈjuːsfəl/","gloss":"útil"},{"surface":"starting","pos":"verb","ipa":"/ˈstɑːrtɪŋ/","gloss":"começando"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-05', 'lesson-pedagogy-c1-cohesion', 5, 'sentence', 'The proposal reduces costs. In addition, it simplifies the process.', 'A proposta reduz custos. Além disso, simplifica o processo.', '/ðə prəˈpoʊzəl rɪˈduːsɪz kɔːsts ɪn əˈdɪʃən ɪt ˈsɪmplɪfaɪz ðə ˈprɑːsɛs/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"proposal","pos":"noun","ipa":"/prəˈpoʊzəl/","gloss":"proposta"},{"surface":"reduces","pos":"verb","ipa":"/rɪˈduːsɪz/","gloss":"reduz"},{"surface":"costs","pos":"verb","ipa":"/kɔːsts/","gloss":"custa"},{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"addition","pos":"noun","ipa":"/əˈdɪʃən/","gloss":"adição; in addition = além disso"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"simplifies","pos":"verb","ipa":"/ˈsɪmplɪfaɪz/","gloss":"simplifica"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"process","pos":"noun","ipa":"/ˈprɑːsɛs/","gloss":"processo"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-06', 'lesson-pedagogy-c1-cohesion', 6, 'sentence', 'The first option is cheaper. The second, however, is more reliable.', 'A primeira opção é mais barata. A segunda, porém, é mais confiável.', '/ðə fɜːrst ˈɑːpʃən ɪz ˈtʃiːpər ðə ˈsɛkənd haʊˈɛvər ɪz mɔːr rɪˈlaɪəbəl/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"},{"surface":"option","pos":"noun","ipa":"/ˈɑːpʃən/","gloss":"opção"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"cheaper","pos":"adjective","ipa":"/ˈtʃiːpər/","gloss":"mais barato"},{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"however","pos":"adverb","ipa":"/haʊˈɛvər/","gloss":"no entanto, mesmo assim"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"reliable","pos":"adjective","ipa":"/rɪˈlaɪəbəl/","gloss":"confiável"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-07', 'lesson-pedagogy-c1-cohesion', 7, 'sentence', 'We tested the system twice. On both occasions, the results were consistent.', 'Testamos o sistema duas vezes. Em ambas as ocasiões, os resultados foram consistentes.', '/wiː ˈtɛstɪd ðə ˈsɪstəm twaɪs ɑːn boʊθ əˈkeɪʒənz ðə rɪˈzʌlts wɜːr kənˈsɪstənt/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"tested","pos":"verb","ipa":"/ˈtɛstɪd/","gloss":"testou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"system","pos":"noun","ipa":"/ˈsɪstəm/","gloss":"sistema"},{"surface":"twice","pos":"adverb","ipa":"/twaɪs/","gloss":"duas vezes"},{"surface":"On","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"both","pos":"determiner","ipa":"/boʊθ/","gloss":"ambos"},{"surface":"occasions","pos":"noun","ipa":"/əˈkeɪʒənz/","gloss":"ocasiões"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"were","pos":"verb","ipa":"/wɜːr/","gloss":"eram, estavam"},{"surface":"consistent","pos":"adjective","ipa":"/kənˈsɪstənt/","gloss":"consistente"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-cohesion-08', 'lesson-pedagogy-c1-cohesion', 8, 'sentence', 'The report recommends a gradual change. Such an approach would reduce the risk.', 'O relatório recomenda uma mudança gradual. Uma abordagem assim reduziria o risco.', '/ðə rɪˈpɔːrt ˌrɛkəˈmɛndz ə ˈɡrædʒuəl tʃeɪndʒ sʌtʃ ən əˈproʊtʃ wʊd rɪˈduːs ðə rɪsk/', 'Expressões como “this finding”, “such an approach” e “these concerns” retomam ideias anteriores. As frases fornecem o contexto necessário para identificar a referência.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"recommends","pos":"verb","ipa":"/ˌrɛkəˈmɛndz/","gloss":"recomenda"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"gradual","pos":"adjective","ipa":"/ˈɡrædʒuəl/","gloss":"gradual"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"Such","pos":"determiner","ipa":"/sʌtʃ/","gloss":"tal, tão"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"approach","pos":"noun","ipa":"/əˈproʊtʃ/","gloss":"abordagem"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"reduce","pos":"verb","ipa":"/rɪˈduːs/","gloss":"reduzir"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"risk","pos":"noun","ipa":"/rɪsk/","gloss":"risco"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-synthesis-01', 'lesson-pedagogy-c1-synthesis', 1, 'sentence', 'The report calls the plan costly. In other words, it would require a large investment.', 'O relatório descreve o plano como caro. Em outras palavras, ele exigiria um grande investimento.', '/ðə rɪˈpɔːrt kɔːlz ðə plæn ˈkɔːstli ɪn ˈʌðər wɜːrdz ɪt wʊd rɪˈkwaɪər ə lɑːrdʒ ɪnˈvɛstmənt/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"calls","pos":"verb","ipa":"/kɔːlz/","gloss":"chama; descreve"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"},{"surface":"costly","pos":"adjective","ipa":"/ˈkɔːstli/","gloss":"caro, custoso"},{"surface":"In","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"other","pos":"pronoun","ipa":"/ˈʌðər/","gloss":"outro"},{"surface":"words","pos":"noun","ipa":"/wɜːrdz/","gloss":"palavras"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"require","pos":"verb","ipa":"/rɪˈkwaɪər/","gloss":"exigir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"large","pos":"adjective","ipa":"/lɑːrdʒ/","gloss":"grande"},{"surface":"investment","pos":"noun","ipa":"/ɪnˈvɛstmənt/","gloss":"investimento"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-02', 'lesson-pedagogy-c1-synthesis', 2, 'sentence', 'One study found an improvement, while another found no clear change.', 'Um estudo encontrou uma melhora, enquanto outro não encontrou uma mudança clara.', '/wʌn ˈstʌdi faʊnd ən ɪmˈpruːvmənt waɪl əˈnʌðər faʊnd noʊ klɪr tʃeɪndʒ/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"One","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"study","pos":"verb","ipa":"/ˈstʌdi/","gloss":"estudar"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"improvement","pos":"noun","ipa":"/ɪmˈpruːvmənt/","gloss":"melhora"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"},{"surface":"no","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-03', 'lesson-pedagogy-c1-synthesis', 3, 'sentence', 'Both reports suggest a benefit, although they differ on its size.', 'Os dois relatórios sugerem um benefício, embora discordem sobre sua dimensão.', '/boʊθ rɪˈpɔːrts səɡˈdʒɛst ə ˈbɛnɪfɪt ɔːlˈðoʊ ðeɪ ˈdɪfər ɑːn ɪts saɪz/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"Both","pos":"determiner","ipa":"/boʊθ/","gloss":"ambos"},{"surface":"reports","pos":"noun","ipa":"/rɪˈpɔːrts/","gloss":"relatórios"},{"surface":"suggest","pos":"verb","ipa":"/səɡˈdʒɛst/","gloss":"sugerir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"benefit","pos":"verb","ipa":"/ˈbɛnɪfɪt/","gloss":"beneficiar-se"},{"surface":"although","pos":"conjunction","ipa":"/ɔːlˈðoʊ/","gloss":"embora"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"differ","pos":"verb","ipa":"/ˈdɪfər/","gloss":"divergir, discordar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"its","pos":"determiner","ipa":"/ɪts/","gloss":"seu, sua (de coisa)"},{"surface":"size","pos":"noun","ipa":"/saɪz/","gloss":"tamanho"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-04', 'lesson-pedagogy-c1-synthesis', 4, 'sentence', 'The results are promising, but they do not establish that the approach works in every context.', 'Os resultados são promissores, mas não demonstram que a abordagem funcione em todos os contextos.', '/ðə rɪˈzʌlts ɑːr ˈprɑːmɪsɪŋ bʌt ðeɪ duː nɑːt ɪˈstæblɪʃ ðæt ðə əˈproʊtʃ wɜːrks ɪn ˈɛvri ˈkɑːntɛkst/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"promising","pos":"adjective","ipa":"/ˈprɑːmɪsɪŋ/","gloss":"promissor"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"they","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"establish","pos":"verb","ipa":"/ɪˈstæblɪʃ/","gloss":"estabelecer, demonstrar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"approach","pos":"noun","ipa":"/əˈproʊtʃ/","gloss":"abordagem"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"context","pos":"noun","ipa":"/ˈkɑːntɛkst/","gloss":"contexto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-05', 'lesson-pedagogy-c1-synthesis', 5, 'sentence', 'Taken together, the findings support a cautious interpretation.', 'Considerados em conjunto, os achados sustentam uma interpretação cautelosa.', '/ˈteɪkən təˈɡɛðər ðə ˈfaɪndɪŋz səˈpɔːrt ə ˈkɔːʃəs ɪnˌtɜːrprəˈteɪʃən/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"Taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"},{"surface":"together","pos":"adverb","ipa":"/təˈɡɛðər/","gloss":"juntos"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"findings","pos":"noun","ipa":"/ˈfaɪndɪŋz/","gloss":"resultados, descobertas"},{"surface":"support","pos":"verb","ipa":"/səˈpɔːrt/","gloss":"apoiar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"cautious","pos":"adjective","ipa":"/ˈkɔːʃəs/","gloss":"cauteloso"},{"surface":"interpretation","pos":"noun","ipa":"/ɪnˌtɜːrprəˈteɪʃən/","gloss":"interpretação"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-06', 'lesson-pedagogy-c1-synthesis', 6, 'sentence', 'The author argues that the change is necessary, rather than merely desirable.', 'O autor defende que a mudança é necessária, e não apenas desejável.', '/ðə ˈɔːθər ˈɑːrɡjuːz ðæt ðə tʃeɪndʒ ɪz ˈnɛsəsɛri ˈræðər ðæn ˈmɪrli dɪˈzaɪrəbəl/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"author","pos":"noun","ipa":"/ˈɔːθər/","gloss":"autor"},{"surface":"argues","pos":"verb","ipa":"/ˈɑːrɡjuːz/","gloss":"argumenta"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"necessary","pos":"adjective","ipa":"/ˈnɛsəsɛri/","gloss":"necessário"},{"surface":"rather","pos":"adverb","ipa":"/ˈræðər/","gloss":"de preferência"},{"surface":"than","pos":"conjunction","ipa":"/ðæn/","gloss":"do que"},{"surface":"merely","pos":"adverb","ipa":"/ˈmɪrli/","gloss":"apenas"},{"surface":"desirable","pos":"adjective","ipa":"/dɪˈzaɪrəbəl/","gloss":"desejável"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-07', 'lesson-pedagogy-c1-synthesis', 7, 'sentence', 'To put it another way, the evidence is useful but still incomplete.', 'Em outras palavras, as evidências são úteis, mas ainda incompletas.', '/tuː pʊt ɪt əˈnʌðər weɪ ðə ˈɛvɪdəns ɪz ˈjuːsfəl bʌt stɪl ˌɪnkəmˈpliːt/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"To","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"put","pos":"verb","ipa":"/pʊt/","gloss":"colocar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"useful","pos":"adjective","ipa":"/ˈjuːsfəl/","gloss":"útil"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"incomplete","pos":"adjective","ipa":"/ˌɪnkəmˈpliːt/","gloss":"incompleto"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-synthesis-08', 'lesson-pedagogy-c1-synthesis', 8, 'sentence', 'Despite their differences, both sources identify the same underlying problem.', 'Apesar das diferenças, as duas fontes identificam o mesmo problema subjacente.', '/dɪˈspaɪt ðɛr ˈdɪfərənsɪz boʊθ ˈsɔːrsɪz aɪˈdɛntɪfaɪ ðə seɪm ˌʌndərˈlaɪɪŋ ˈprɑːbləm/', 'Os pares de informações já estão nas frases. Observe a reformulação com “in other words” e a síntese que preserva contraste, limites e grau de certeza.', '[]'::jsonb, '[{"surface":"Despite","pos":"preposition","ipa":"/dɪˈspaɪt/","gloss":"apesar de"},{"surface":"their","pos":"determiner","ipa":"/ðɛr/","gloss":"deles, delas"},{"surface":"differences","pos":"noun","ipa":"/ˈdɪfərənsɪz/","gloss":"diferenças"},{"surface":"both","pos":"determiner","ipa":"/boʊθ/","gloss":"ambos"},{"surface":"sources","pos":"noun","ipa":"/ˈsɔːrsɪz/","gloss":"fontes"},{"surface":"identify","pos":"verb","ipa":"/aɪˈdɛntɪfaɪ/","gloss":"identificar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"same","pos":"adjective","ipa":"/seɪm/","gloss":"mesmo"},{"surface":"underlying","pos":"adjective","ipa":"/ˌʌndərˈlaɪɪŋ/","gloss":"subjacente"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-pedagogy-c1-context-register-01', 'lesson-pedagogy-c1-context-register', 1, 'sentence', 'The window is open, and I''m cold. Would you mind closing it?', 'A janela está aberta, e estou com frio. Você se importaria de fechá-la?', '/ðə ˈwɪndoʊ ɪz ˈoʊpən ænd aɪm koʊld wʊd juː maɪnd ˈkloʊzɪŋ ɪt/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","gloss":"janela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"Would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mind","pos":"verb","ipa":"/maɪnd/","gloss":"se importar"},{"surface":"closing","pos":"verb","ipa":"/ˈkloʊzɪŋ/","gloss":"fechando"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-02', 'lesson-pedagogy-c1-context-register', 2, 'sentence', 'Your proposal is interesting, but I have some concerns about the cost.', 'Sua proposta é interessante, mas tenho algumas preocupações com o custo.', '/jʊr prəˈpoʊzəl ɪz ˈɪntrəstɪŋ bʌt aɪ hæv sʌm kənˈsɜːrnz əˈbaʊt ðə kɔːst/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"Your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"proposal","pos":"noun","ipa":"/prəˈpoʊzəl/","gloss":"proposta"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"interesting","pos":"adjective","ipa":"/ˈɪntrəstɪŋ/","gloss":"interessante"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"concerns","pos":"noun","ipa":"/kənˈsɜːrnz/","gloss":"preocupações"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"cost","pos":"verb","ipa":"/kɔːst/","gloss":"custar"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-03', 'lesson-pedagogy-c1-context-register', 3, 'sentence', 'I see your point. Nevertheless, I would prefer to review the evidence first.', 'Entendo seu argumento. Ainda assim, eu preferiria analisar as evidências primeiro.', '/aɪ siː jʊr pɔɪnt ˌnɛvərðəˈlɛs aɪ wʊd prɪˈfɜːr tuː rɪˈvjuː ðə ˈɛvɪdəns fɜːrst/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"Nevertheless","pos":"adverb","ipa":"/ˌnɛvərðəˈlɛs/","gloss":"no entanto"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"prefer","pos":"verb","ipa":"/prɪˈfɜːr/","gloss":"preferir"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"review","pos":"noun","ipa":"/rɪˈvjuː/","gloss":"avaliação"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"evidence","pos":"noun","ipa":"/ˈɛvɪdəns/","gloss":"evidência"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-04', 'lesson-pedagogy-c1-context-register', 4, 'sentence', 'I appreciate the invitation, but I''m afraid I won''t be able to attend.', 'Agradeço o convite, mas infelizmente não poderei participar.', '/aɪ əˈpriːʃieɪt ðə ˌɪnvɪˈteɪʃən bʌt aɪm əˈfreɪd aɪ woʊnt biː ˈeɪbəl tuː əˈtɛnd/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"appreciate","pos":"verb","ipa":"/əˈpriːʃieɪt/","gloss":"agradecer, valorizar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"invitation","pos":"noun","ipa":"/ˌɪnvɪˈteɪʃən/","gloss":"convite"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"afraid","pos":"adjective","ipa":"/əˈfreɪd/","gloss":"com medo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"won''t","pos":"modal verb","ipa":"/woʊnt/","gloss":"não vai (will not)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"able","pos":"adjective","ipa":"/ˈeɪbəl/","gloss":"capaz"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"attend","pos":"verb","ipa":"/əˈtɛnd/","gloss":"comparecer"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-05', 'lesson-pedagogy-c1-context-register', 5, 'sentence', 'Could we revisit this issue once we have more information?', 'Poderíamos retomar esta questão quando tivermos mais informações?', '/kʊd wiː ˌriːˈvɪzɪt ðɪs ˈɪʃuː wʌns wiː hæv mɔːr ˌɪnfərˈmeɪʃən/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"revisit","pos":"verb","ipa":"/ˌriːˈvɪzɪt/","gloss":"retomar, reexaminar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"issue","pos":"noun","ipa":"/ˈɪʃuː/","gloss":"assunto, problema"},{"surface":"once","pos":"adverb","ipa":"/wʌns/","gloss":"uma vez"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"information","pos":"noun","ipa":"/ˌɪnfərˈmeɪʃən/","gloss":"informação"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-06', 'lesson-pedagogy-c1-context-register', 6, 'sentence', 'That may be true in some cases, though it does not explain these results.', 'Isso pode ser verdade em alguns casos, embora não explique estes resultados.', '/ðæt meɪ biː truː ɪn sʌm ˈkeɪsɪz ðoʊ ɪt dʌz nɑːt ɪkˈspleɪn ðiːz rɪˈzʌlts/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"may","pos":"modal verb","ipa":"/meɪ/","gloss":"poder (permissão formal)"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"true","pos":"adjective","ipa":"/truː/","gloss":"verdadeiro"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"cases","pos":"noun","ipa":"/ˈkeɪsɪz/","gloss":"casos"},{"surface":"though","pos":"conjunction","ipa":"/ðoʊ/","gloss":"embora"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"explain","pos":"verb","ipa":"/ɪkˈspleɪn/","gloss":"explicar"},{"surface":"these","pos":"determiner","ipa":"/ðiːz/","gloss":"estes, estas"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-07', 'lesson-pedagogy-c1-context-register', 7, 'sentence', 'I don''t mean to dismiss the idea; I simply think we need a clearer plan.', 'Não pretendo descartar a ideia; apenas acho que precisamos de um plano mais claro.', '/aɪ doʊnt miːn tuː dɪsˈmɪs ðə aɪˈdiːə aɪ ˈsɪmpli θɪŋk wiː niːd ə ˈklɪrər plæn/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"dismiss","pos":"verb","ipa":"/dɪsˈmɪs/","gloss":"descartar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"idea","pos":"noun","ipa":"/aɪˈdiːə/","gloss":"ideia"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"simply","pos":"adverb","ipa":"/ˈsɪmpli/","gloss":"com simplicidade"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"clearer","pos":"adjective","ipa":"/ˈklɪrər/","gloss":"mais claro"},{"surface":"plan","pos":"noun","ipa":"/plæn/","gloss":"plano"}]'::jsonb, NULL, NULL),
  ('unit-pedagogy-c1-context-register-08', 'lesson-pedagogy-c1-context-register', 8, 'sentence', 'For a formal report, I would replace that expression with a more neutral one.', 'Para um relatório formal, eu substituiria essa expressão por uma mais neutra.', '/fɔːr ə ˈfɔːrməl rɪˈpɔːrt aɪ wʊd rɪˈpleɪs ðæt ɪkˈsprɛʃən wɪð ə mɔːr ˈnuːtrəl wʌn/', 'Considere quem fala, a situação e as frases seguintes. Pedidos indiretos e ressalvas admitem interpretações; a frase isolada não prova sarcasmo nem intenção.', '[]'::jsonb, '[{"surface":"For","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"formal","pos":"adjective","ipa":"/ˈfɔːrməl/","gloss":"formal"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"replace","pos":"verb","ipa":"/rɪˈpleɪs/","gloss":"substituir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"expression","pos":"noun","ipa":"/ɪkˈsprɛʃən/","gloss":"expressão"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"neutral","pos":"adjective","ipa":"/ˈnuːtrəl/","gloss":"neutro"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"}]'::jsonb, NULL, NULL)
